window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2025-3"]={"track":"written","round":"2025-3","questions":[{"id":"written-2025-3-1","no":1,"unit":"소프트웨어 설계","q":"UI 설계 시 사용자 측면의 요구사항 가운데, 사용자가 원하는 목표를 이루기 위해 수행할 내용을 기술하는 것은?","choices":["레이아웃","스토리보드","프로토타입","유스케이스"],"ans":4,"exp":{"concept":"유스케이스(Use Case)는 사용자가 시스템을 이용해 이루고 싶은 목표와, 그 목표를 위해 사용자와 시스템이 주고받는 일을 시나리오로 적은 것이다. UI 설계에서 사용자 측면의 요구사항을 정리할 때 쓰인다. 식당에 비유하면 ‘손님이 음식을 주문해 받기까지 무엇을 하는지’를 순서대로 적은 것과 같다.","choices":[{"verdict":"오답","why":"레이아웃(Layout)은 화면 안에 메뉴·버튼·입력란 같은 요소를 어디에 배치할지 정한 것이다. 사용자가 목표를 위해 수행할 내용을 기술한 것이 아니다."},{"verdict":"오답","why":"스토리보드(Storyboard)는 화면 구성, 화면 흐름, 기능 설명 등을 한데 정리한 UI 설계 산출물이다. 사용자 목표 달성 과정을 기술하는 요구사항 표현 방식은 아니다."},{"verdict":"오답","why":"프로토타입(Prototype)은 실제 화면처럼 동작하도록 만든 견본으로, 사용자 검증을 위해 만든다. 요구사항을 글로 기술한 것이 아니다."},{"verdict":"정답","why":"유스케이스는 사용자가 원하는 목표를 이루기 위해 시스템과 주고받는 수행 내용을 기술한 것이므로 정답이다."}],"keywords":[{"term":"유스케이스(Use Case)","desc":"사용자가 목표를 이루기 위해 시스템과 주고받는 기능을 시나리오로 기술한 것"},{"term":"스토리보드(Storyboard)","desc":"화면 구성·흐름·기능 설명을 담은 UI 설계 산출물"},{"term":"프로토타입(Prototype)","desc":"실제처럼 동작하는 견본 화면, 사용자 피드백 수집용"}],"memo":"‘사용자가 원하는 목표를 이루기 위해 수행할 내용’이라는 표현이 나오면 유스케이스다."}},{"id":"written-2025-3-2","no":2,"unit":"소프트웨어 설계","q":"GoF(Gang of Four) 디자인 패턴을 생성, 구조, 행동 패턴의 세 그룹으로 나눌 때, 다음 중 구조 패턴에 해당하지 않는 것은?","choices":["Bridge 패턴","Proxy 패턴","Builder 패턴","Adapter 패턴"],"ans":3,"exp":{"concept":"GoF 디자인 패턴 23개는 생성·구조·행동 세 그룹으로 나뉜다. 생성 패턴은 객체를 만드는 방법, 구조 패턴은 클래스나 객체를 조합해 더 큰 구조를 만드는 방법, 행동 패턴은 객체 사이의 책임 분배와 상호작용을 다룬다. Builder는 복잡한 객체를 단계별로 조립해 만드는 생성 패턴이다.","choices":[{"verdict":"오답","why":"Bridge 패턴은 기능 계층과 구현 계층을 분리해 각각 독립적으로 확장할 수 있게 하는 구조 패턴이다."},{"verdict":"오답","why":"Proxy 패턴은 실제 객체 대신 대리 객체를 두어 접근을 제어하는 구조 패턴이다."},{"verdict":"정답","why":"Builder 패턴은 복잡한 객체의 생성 과정을 단계별로 나누어 조립하는 생성 패턴이므로 구조 패턴이 아니다."},{"verdict":"오답","why":"Adapter 패턴은 호환되지 않는 인터페이스를 맞춰 함께 동작하게 하는 구조 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"구조 패턴","desc":"Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy"},{"term":"행동 패턴","desc":"Observer, Strategy, State, Command, Iterator, Template Method 등"}],"memo":"생성 패턴은 다섯 개뿐이다(추상 팩토리, 빌더, 팩토리 메서드, 프로토타입, 싱글톤). 이 다섯을 외우면 나머지 구조·행동 구분이 쉬워진다."}},{"id":"written-2025-3-3","no":3,"unit":"소프트웨어 설계","q":"소프트웨어 개발 방법 가운데 요구사항 분석(Requirements Analysis)과 거리가 먼 것은?","choices":["비용 및 일정에 대한 제약 설정","타당성 조사","설계 명세서 작성","요구사항 정의 문서화"],"ans":3,"exp":{"concept":"요구사항 분석은 ‘무엇을 만들어야 하는가’를 정하는 단계다. 타당성을 조사하고, 비용과 일정의 제약을 정하고, 요구사항을 정의해 문서로 남긴다. ‘어떻게 만들 것인가’를 정하는 설계 명세서는 그다음 단계인 설계 단계의 산출물이다.","choices":[{"verdict":"오답","why":"비용과 일정에 대한 제약을 정하는 것은 요구사항 분석 단계에서 하는 일이다."},{"verdict":"오답","why":"개발이 기술적·경제적으로 가능한지 따지는 타당성 조사는 요구사항 분석 단계에서 이루어진다."},{"verdict":"정답","why":"설계 명세서 작성은 요구사항 분석이 끝난 뒤 설계 단계에서 하는 일이므로 요구사항 분석과 거리가 멀다."},{"verdict":"오답","why":"요구사항을 정의하고 요구사항 명세서로 문서화하는 것은 요구사항 분석의 핵심 활동이다."}],"keywords":[{"term":"요구사항 분석","desc":"사용자 요구를 이해하고 정리해 무엇을 만들지 정하는 단계"},{"term":"요구사항 명세서","desc":"요구사항 분석의 결과를 정리한 문서(SRS)"},{"term":"설계 명세서","desc":"어떻게 만들지 정리한 설계 단계의 산출물"}],"memo":"분석은 ‘무엇(What)’, 설계는 ‘어떻게(How)’. ‘설계’라는 말이 들어간 보기는 분석 단계가 아니다."}},{"id":"written-2025-3-4","no":4,"unit":"소프트웨어 설계","q":"익스트림 프로그래밍(XP)의 5가지 가치와 거리가 먼 것은?","choices":["피드백","정형 분석","의사소통","용기"],"ans":2,"exp":{"concept":"익스트림 프로그래밍(XP, eXtreme Programming)은 짧은 주기로 자주 릴리스하며 고객 요구 변화에 빠르게 대응하는 애자일 방법론이다. XP의 5가지 가치는 의사소통(Communication), 단순성(Simplicity), 용기(Courage), 존중(Respect), 피드백(Feedback)이다.","choices":[{"verdict":"오답","why":"피드백(Feedback)은 XP의 5가지 가치 중 하나다."},{"verdict":"정답","why":"정형 분석은 수학적 표기로 요구사항을 엄밀하게 다루는 기법으로, XP의 가치에 포함되지 않는다."},{"verdict":"오답","why":"의사소통(Communication)은 XP의 5가지 가치 중 하나다."},{"verdict":"오답","why":"용기(Courage)는 XP의 5가지 가치 중 하나다."}],"keywords":[{"term":"XP 5가지 가치","desc":"의사소통, 단순성, 용기, 존중, 피드백"},{"term":"XP 주요 실천 방법","desc":"짝 프로그래밍, 테스트 주도 개발, 지속적인 통합, 리팩토링, 작은 릴리스 등"},{"term":"애자일(Agile)","desc":"변화에 빠르게 대응하며 반복적으로 개발하는 방법론의 총칭"}],"memo":"XP 가치는 ‘의단용존피’(의사소통, 단순성, 용기, 존중, 피드백)로 외운다."}},{"id":"written-2025-3-5","no":5,"unit":"소프트웨어 설계","q":"UML에서 사용되는 다이어그램 가운데, 시스템의 동작을 나타내는 행위(Behavioral) 다이어그램에 속하지 않는 것은?","choices":["시퀀스 다이어그램(Sequence Diagram)","유스케이스 다이어그램(Use Case Diagram)","활동 다이어그램(Activity Diagram)","배치 다이어그램(Deployment Diagram)"],"ans":4,"exp":{"concept":"UML 다이어그램은 시스템의 정적인 모습을 그리는 구조(Structural) 다이어그램과 시간에 따른 동작을 그리는 행위(Behavioral) 다이어그램으로 나뉜다. 배치 다이어그램은 소프트웨어가 어떤 하드웨어(노드)에 놓이는지를 그리는 구조 다이어그램이다.","choices":[{"verdict":"오답","why":"시퀀스 다이어그램은 객체들이 주고받는 메시지를 시간 순서로 표현하는 행위 다이어그램이다."},{"verdict":"오답","why":"유스케이스 다이어그램은 사용자 관점에서 시스템 기능을 표현하는 행위 다이어그램이다."},{"verdict":"오답","why":"활동 다이어그램은 처리 흐름을 순서대로 표현하는 행위 다이어그램이다."},{"verdict":"정답","why":"배치 다이어그램(Deployment Diagram)은 물리적 노드와 그 위에 배치된 소프트웨어 구성을 나타내는 구조 다이어그램이므로 행위 다이어그램이 아니다."}],"keywords":[{"term":"구조 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합 구조, 패키지"},{"term":"행위 다이어그램","desc":"유스케이스, 시퀀스, 커뮤니케이션, 상태, 활동, 상호작용 개요, 타이밍"},{"term":"배치 다이어그램","desc":"하드웨어 노드와 그 위의 소프트웨어 배치를 표현"}],"memo":"‘배치·컴포넌트·패키지·클래스·객체’처럼 물건이 놓인 모습이면 구조, 시간이 흐르는 그림이면 행위로 구분한다."}},{"id":"written-2025-3-6","no":6,"unit":"소프트웨어 설계","q":"다음 설명에 해당하는 도표는 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>시스템의 기능을 여러 개의 고유 모듈로 나누고 이들 간의 인터페이스를 계층 구조로 나타낸 것으로, 가시적 도표(Visual Table of Contents), 총체적 도표(Overview Diagram), 세부적 도표(Detail Diagram)가 있다.</p></div>","choices":["Burn-down Chart","HIPO Chart","Visual Diagram","Flow Chart"],"ans":2,"exp":{"concept":"HIPO(Hierarchy Input Process Output) 차트는 시스템 기능을 여러 모듈로 나누고 모듈 사이 관계를 계층 구조로 나타낸 도표다. 하향식 개발에 쓰이며 가시적 도표, 총체적 도표, 세부적 도표 세 가지로 구성된다. 책의 목차처럼 큰 기능에서 작은 기능으로 내려가며 보여 준다.","choices":[{"verdict":"오답","why":"번다운 차트(Burn-down Chart)는 스크럼에서 남은 작업량을 시간 흐름에 따라 줄어드는 그래프로 나타낸 것이다."},{"verdict":"정답","why":"HIPO 차트는 가시적 도표, 총체적 도표, 세부적 도표로 구성되므로 정답이다."},{"verdict":"오답","why":"Visual Diagram은 출제 범위의 표준 도표 이름이 아니다. 지문의 ‘가시적 도표(Visual Table of Contents)’는 HIPO의 구성 요소다."},{"verdict":"오답","why":"순서도(Flow Chart)는 처리 순서를 기호와 화살표로 나타낸 그림으로, 모듈을 계층 구조로 나타내는 도표가 아니다."}],"keywords":[{"term":"HIPO","desc":"Hierarchy Input Process Output, 기능을 계층적으로 표현하는 도구"},{"term":"가시적 도표","desc":"시스템 전체 기능과 흐름을 계층으로 보여 주는 도표(Visual Table of Contents)"},{"term":"총체적 도표·세부적 도표","desc":"기능별 입력·처리·출력 전반을 보여 주는 도표와, 그 기본 요소를 상세히 기술한 도표"}],"memo":"‘가시적·총체적·세부적 도표’ 세 단어가 보이면 바로 HIPO다."}},{"id":"written-2025-3-7","no":7,"unit":"소프트웨어 설계","q":"하나의 모듈 안에 있는 구성 요소들이 공통의 목적을 이루기 위해 서로 어느 정도 관련되어 있는지, 그 기능적 연관의 정도를 나타내는 것은?","choices":["Unity","Cohesion","Structure","Coupling"],"ans":2,"exp":{"concept":"응집도(Cohesion)는 한 모듈 안의 구성 요소들이 하나의 목적을 위해 얼마나 똘똘 뭉쳐 있는지를 나타낸다. 결합도(Coupling)는 서로 다른 모듈 사이의 의존 정도다. 좋은 설계는 응집도는 높이고 결합도는 낮춘다.","choices":[{"verdict":"오답","why":"Unity는 출제 범위의 표준 설계 용어가 아니다."},{"verdict":"정답","why":"응집도(Cohesion)는 모듈 내부 구성 요소들의 기능적 연관 정도이므로 정답이다."},{"verdict":"오답","why":"Structure(구조)는 모듈 내부의 기능적 연관 정도를 가리키는 용어가 아니다."},{"verdict":"오답","why":"결합도(Coupling)는 모듈 내부가 아니라 모듈과 모듈 사이의 의존 정도를 나타낸다."}],"keywords":[{"term":"응집도(Cohesion)","desc":"모듈 내부 요소들의 기능적 연관 정도, 높을수록 좋음"},{"term":"결합도(Coupling)","desc":"모듈 간 상호 의존 정도, 낮을수록 좋음"},{"term":"기능적 응집도","desc":"모듈 내부 요소가 단일 기능을 위해 수행되는, 가장 강한 응집도"}],"memo":"응집도는 안(내부), 결합도는 밖(모듈 사이). ‘하나의 모듈 안’이라는 말이 나오면 응집도다."}},{"id":"written-2025-3-8","no":8,"unit":"소프트웨어 설계","q":"요구사항 명세 기법에 관한 설명 중 틀린 것은?","choices":["정형 명세 기법은 비정형 명세 기법과 비교하여 표현이 간결하다.","비정형 명세 기법은 사용자의 요구를 표현할 때 자연어에 기반하여 서술한다.","비정형 명세 기법은 사용자의 요구를 표현할 때 Z 비정형 명세 기법을 이용한다.","정형 명세 기법은 사용자의 요구를 표현할 때 수학적인 원리와 표기법을 사용한다."],"ans":3,"exp":{"concept":"요구사항 명세 기법은 수학적 원리와 기호를 쓰는 정형 명세와, 자연어·그림을 쓰는 비정형 명세로 나뉜다. Z는 집합론과 논리를 바탕으로 한 대표적인 정형 명세 언어다. 따라서 비정형 명세가 Z를 이용한다는 설명은 틀렸다.","choices":[{"verdict":"오답","why":"정형 명세는 수학 기호로 표현하므로 비정형 명세보다 표현이 간결하고 명확하다."},{"verdict":"오답","why":"비정형 명세는 자연어, 다이어그램 등을 기반으로 서술한다."},{"verdict":"정답","why":"Z는 비정형이 아니라 정형 명세 기법이다. 비정형 명세는 자연어 기반이므로 이 설명이 틀렸다."},{"verdict":"오답","why":"정형 명세는 수학적 원리와 표기법을 사용해 요구사항을 표현한다."}],"keywords":[{"term":"정형 명세","desc":"수학적 기호로 표현, 간결·명확, 이해하기 어려움. Z, VDM, Petri-net, CSP 등"},{"term":"비정형 명세","desc":"자연어·다이어그램 기반, 이해하기 쉬우나 모호할 수 있음. FSM, Decision Table, ER 모델 등"},{"term":"Z 명세","desc":"집합론과 술어 논리 기반의 정형 명세 언어"}],"memo":"Z는 정형 명세의 대표. ‘Z 비정형’이라는 조합이 보이면 틀린 문장이다."}},{"id":"written-2025-3-9","no":9,"unit":"소프트웨어 설계","q":"결합도(Coupling)에 관한 설명으로 옳지 않은 것은?","choices":["공통 결합도(Common Coupling)는 두 모듈이 동일한 전역 데이터에 접근한다면 공통 결합되어 있다고 한다.","데이터 결합도(Data Coupling)는 두 모듈이 매개 변수로 자료를 전달할 때 자료 구조 형태로 전달되어 이용되면 데이터가 결합되어 있다고 한다.","결합도(Coupling)는 두 모듈 간의 상호작용 또는 의존도의 정도를 나타내는 것이다.","내용 결합도(Content Coupling)는 하나의 모듈이 다른 모듈의 내용을 직접적으로 참조할 때 두 모듈은 내용적으로 결합되어 있다고 한다."],"ans":2,"exp":{"concept":"결합도는 모듈 사이의 의존 정도다. 매개변수로 단순한 값만 넘기면 데이터 결합도, 배열이나 레코드 같은 자료 구조를 통째로 넘기면 스탬프 결합도라 한다. 같은 전역 데이터를 함께 쓰면 공통 결합도, 다른 모듈 내부를 직접 참조하면 내용 결합도다.","choices":[{"verdict":"오답","why":"두 모듈이 동일한 전역 데이터에 접근하면 공통 결합도(Common Coupling)다."},{"verdict":"정답","why":"자료 구조 형태로 전달하는 것은 스탬프 결합도(Stamp Coupling)의 설명이다. 데이터 결합도는 단순한 데이터 값만 매개변수로 전달하는 경우다."},{"verdict":"오답","why":"결합도는 두 모듈 간의 상호작용 또는 의존도의 정도를 나타낸다."},{"verdict":"오답","why":"하나의 모듈이 다른 모듈의 내부를 직접 참조하면 내용 결합도(Content Coupling)다."}],"keywords":[{"term":"데이터 결합도","desc":"단순한 값만 매개변수로 전달, 가장 약한(좋은) 결합"},{"term":"스탬프 결합도","desc":"배열·레코드 등 자료 구조를 전달"},{"term":"결합도 순서(약→강)","desc":"자료 < 스탬프 < 제어 < 외부 < 공통 < 내용"}],"memo":"결합도 순서는 ‘자스제외공내’. ‘자료 구조’를 넘기면 데이터가 아니라 스탬프다."}},{"id":"written-2025-3-10","no":10,"unit":"소프트웨어 설계","q":"분산 시스템의 미들웨어(Middleware)에 대한 설명 중 틀린 것은?","choices":["애플리케이션과 사용자 사이에서만 분산 서비스를 제공하는 것이다.","위치 투명성(Location Transparency)을 제공한다.","분산 시스템의 여러 컴포넌트가 요구하는 재사용 가능한 서비스의 구현을 제공해 준다.","분산 시스템에서 다양한 부분을 관리·통신하고 데이터를 교환할 수 있게 해주는 소프트웨어로 볼 수 있다."],"ans":1,"exp":{"concept":"미들웨어(Middleware)는 운영체제와 응용 프로그램 사이, 또는 클라이언트와 서버 사이에서 서로 다른 시스템이 통신하고 데이터를 주고받도록 이어 주는 소프트웨어다. 위치를 몰라도 자원을 쓸 수 있게 하는 위치 투명성 등을 제공한다.","choices":[{"verdict":"정답","why":"미들웨어는 애플리케이션과 사용자 사이에서만 서비스를 제공하는 것이 아니라, 응용 프로그램과 운영체제·네트워크, 클라이언트와 서버 등 시스템 구성 요소 사이를 연결한다. ‘사용자 사이에서만’이라는 한정이 틀렸다."},{"verdict":"오답","why":"미들웨어는 자원이 실제로 어디 있는지 몰라도 접근할 수 있는 위치 투명성을 제공한다."},{"verdict":"오답","why":"미들웨어는 분산 시스템의 여러 컴포넌트가 공통으로 쓰는 재사용 가능한 서비스(통신, 트랜잭션 등)를 구현해 제공한다."},{"verdict":"오답","why":"미들웨어는 분산 시스템의 여러 부분을 관리하고 서로 통신·데이터 교환하게 해 주는 소프트웨어다."}],"keywords":[{"term":"미들웨어(Middleware)","desc":"서로 다른 시스템·응용 사이를 연결해 통신과 데이터 교환을 돕는 소프트웨어"},{"term":"위치 투명성","desc":"자원의 물리적 위치를 몰라도 접근할 수 있는 성질"},{"term":"미들웨어 종류","desc":"DB, RPC, MOM, TP-Monitor, ORB, WAS 등"}],"memo":"‘~에서만’처럼 범위를 좁히는 표현이 들어간 보기는 틀린 경우가 많다."}},{"id":"written-2025-3-11","no":11,"unit":"소프트웨어 설계","q":"객체지향 설계 원칙 가운데 SOLID 원칙이라 불리는 것에 해당하지 않는 것은 다음 중 무엇인가?","choices":["LSP(Liskov Substitution Principle)","SSO(Single Sign On)","DIP(Dependency Inversion Principle)","ISP(Interface Segregation Principle)"],"ans":2,"exp":{"concept":"SOLID는 객체지향 설계의 다섯 원칙의 첫 글자를 모은 말이다. 단일 책임(SRP), 개방-폐쇄(OCP), 리스코프 치환(LSP), 인터페이스 분리(ISP), 의존 역전(DIP)이다.","choices":[{"verdict":"오답","why":"LSP(리스코프 치환 원칙)는 자식 클래스가 부모 클래스를 대체해도 문제없이 동작해야 한다는 SOLID 원칙이다."},{"verdict":"정답","why":"SSO(Single Sign On)는 한 번 로그인으로 여러 시스템을 이용하게 하는 인증 방식으로, 설계 원칙이 아니다."},{"verdict":"오답","why":"DIP(의존 역전 원칙)는 구체적인 것이 아니라 추상화에 의존해야 한다는 SOLID 원칙이다."},{"verdict":"오답","why":"ISP(인터페이스 분리 원칙)는 사용하지 않는 메서드에 의존하지 않도록 인터페이스를 잘게 나눠야 한다는 SOLID 원칙이다."}],"keywords":[{"term":"SRP","desc":"Single Responsibility Principle, 클래스는 하나의 책임만"},{"term":"OCP","desc":"Open-Closed Principle, 확장에는 열리고 수정에는 닫힘"},{"term":"LSP·ISP·DIP","desc":"리스코프 치환, 인터페이스 분리, 의존 역전 원칙"},{"term":"SSO(Single Sign On)","desc":"한 번의 인증으로 여러 서비스를 이용하는 인증 방식"}],"memo":"S-O-L-I-D 각 글자가 SRP, OCP, LSP, ISP, DIP의 첫 글자다. 끝이 P(Principle)가 아닌 보기는 원칙이 아니다."}},{"id":"written-2025-3-12","no":12,"unit":"소프트웨어 설계","q":"UI 설계 지침으로 옳지 않은 것은?","choices":["주요 기능을 메인 화면에 노출시켜 조작이 쉽도록 해야 한다.","치명적인 오류에 관한 부정적인 사항은 사용자가 인지하지 못하도록 한다.","사용자의 직무, 연령, 성별 등 다양한 계층을 수용해야 한다.","이해하기 편하고 사용하기 쉬운 환경을 제공하여야 한다."],"ans":2,"exp":{"concept":"UI 설계 지침은 사용자가 쉽고 정확하게 쓸 수 있게 하는 원칙이다. 사용자 중심, 일관성, 단순성, 결과 예측 가능, 가시성, 표준화, 접근성, 명확성, 오류 발생 해결 등이 있다. 오류가 생기면 사용자가 알아차리고 대처할 수 있도록 정확히 알려 주어야 한다.","choices":[{"verdict":"오답","why":"주요 기능을 메인 화면에 노출해 조작을 쉽게 하는 것은 가시성 지침에 맞다."},{"verdict":"정답","why":"치명적인 오류는 숨기는 것이 아니라 사용자가 정확히 인지하고 대처할 수 있도록 알려야 한다. 따라서 옳지 않은 지침이다."},{"verdict":"오답","why":"직무, 연령, 성별 등 다양한 계층을 수용하는 것은 접근성 지침에 맞다."},{"verdict":"오답","why":"이해하기 편하고 사용하기 쉬운 환경을 제공하는 것은 사용자 중심 지침에 맞다."}],"keywords":[{"term":"가시성","desc":"주요 기능을 메인 화면에 노출해 쉽게 조작하도록 함"},{"term":"접근성","desc":"직무·연령·성별 등 다양한 사용자 계층을 수용"},{"term":"오류 발생 해결","desc":"오류가 발생하면 사용자가 정확히 인지할 수 있도록 설계"}],"memo":"UI 지침에서 ‘사용자가 인지하지 못하도록’ 같은 숨기는 표현은 항상 틀린 보기다."}},{"id":"written-2025-3-13","no":13,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴 가운데 생성 패턴에 해당하는 것은?","choices":["Decorator Pattern","Singleton Pattern","Adapter Pattern","State Pattern"],"ans":2,"exp":{"concept":"GoF 생성 패턴은 객체를 어떻게 만들지 다루는 패턴으로 Abstract Factory, Builder, Factory Method, Prototype, Singleton 다섯 개다. Singleton은 클래스의 인스턴스를 하나만 만들고 어디서든 그 하나를 쓰게 하는 패턴이다.","choices":[{"verdict":"오답","why":"Decorator 패턴은 객체에 기능을 동적으로 덧붙이는 구조 패턴이다."},{"verdict":"정답","why":"Singleton 패턴은 인스턴스를 하나만 생성하도록 보장하는 생성 패턴이므로 정답이다."},{"verdict":"오답","why":"Adapter 패턴은 호환되지 않는 인터페이스를 연결하는 구조 패턴이다."},{"verdict":"오답","why":"State 패턴은 객체의 상태에 따라 행동을 바꾸는 행동 패턴이다."}],"keywords":[{"term":"Singleton","desc":"인스턴스를 단 하나만 생성해 공유하는 생성 패턴"},{"term":"생성 패턴","desc":"Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"Decorator","desc":"기존 객체에 기능을 덧붙이는 구조 패턴"}],"memo":"생성 패턴은 ‘추빌팩프싱’(추상 팩토리, 빌더, 팩토리 메서드, 프로토타입, 싱글톤)으로 외운다."}},{"id":"written-2025-3-14","no":14,"unit":"소프트웨어 설계","q":"UI의 종류 가운데 멀티 터치(Multi-touch), 동작 인식(Gesture Recognition) 등 사용자의 자연스러운 움직임을 인식해 서로 주고받는 정보를 제공하는 사용자 인터페이스를 뜻하는 것은?","choices":["CLI(Command Line Interface)","GUI(Graphical User Interface)","NUI(Natural User Interface)","OUI(Organic User Interface)"],"ans":3,"exp":{"concept":"UI는 입력 방식에 따라 나뉜다. CLI는 명령어를 글자로 입력하고, GUI는 마우스로 그래픽 화면을 조작한다. NUI(Natural User Interface)는 터치, 몸짓, 음성처럼 사람의 자연스러운 행동으로 기기를 조작하는 방식이다.","choices":[{"verdict":"오답","why":"CLI(Command Line Interface)는 키보드로 명령어를 입력해 조작하는 텍스트 방식 인터페이스다."},{"verdict":"오답","why":"GUI(Graphical User Interface)는 아이콘·창 등 그래픽 요소를 마우스로 조작하는 인터페이스다."},{"verdict":"정답","why":"NUI(Natural User Interface)는 멀티 터치, 동작 인식 등 사용자의 자연스러운 움직임으로 조작하는 인터페이스이므로 정답이다."},{"verdict":"오답","why":"OUI(Organic User Interface)는 모든 사물이 입출력 장치가 될 수 있는 형태의 인터페이스를 말한다. 자연스러운 몸짓 인식이라는 설명에는 NUI가 해당한다."}],"keywords":[{"term":"CLI","desc":"명령어 텍스트 입력 방식"},{"term":"GUI","desc":"그래픽 화면과 마우스 조작 방식"},{"term":"NUI","desc":"터치·동작·음성 등 자연스러운 행동으로 조작"},{"term":"OUI","desc":"모든 사물이 입출력 장치로 쓰일 수 있는 인터페이스"}],"memo":"‘자연스러운(Natural)’이라는 단어가 문제에 그대로 들어 있다. 멀티 터치·제스처는 NUI다."}},{"id":"written-2025-3-15","no":15,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh)의 객체지향 분석 절차를 순서대로 가장 올바르게 나열한 것은?","choices":["객체 모형 → 동적 모형 → 기능 모형","기능 모형 → 동적 모형 → 객체 모형","객체 모형 → 기능 모형 → 동적 모형","기능 모형 → 객체 모형 → 동적 모형"],"ans":1,"exp":{"concept":"럼바우(Rumbaugh)의 객체지향 분석 기법(OMT)은 세 가지 모델링을 순서대로 한다. 먼저 객체와 관계를 정의하는 객체 모델링, 다음으로 시간에 따른 상태 변화를 그리는 동적 모델링, 마지막으로 데이터가 어떻게 처리되는지 그리는 기능 모델링이다.","choices":[{"verdict":"정답","why":"객체 모형 → 동적 모형 → 기능 모형은 럼바우 분석 절차의 올바른 순서다."},{"verdict":"오답","why":"기능 모형이 가장 마지막이므로 순서가 틀렸다."},{"verdict":"오답","why":"동적 모형이 기능 모형보다 먼저 와야 하므로 순서가 틀렸다."},{"verdict":"오답","why":"객체 모형이 가장 먼저 와야 하므로 순서가 틀렸다."}],"keywords":[{"term":"객체 모델링","desc":"객체 다이어그램으로 객체와 관계를 표현"},{"term":"동적 모델링","desc":"상태 다이어그램으로 시간에 따른 상태 변화를 표현"},{"term":"기능 모델링","desc":"자료 흐름도(DFD)로 데이터 처리 과정을 표현"}],"memo":"럼바우는 ‘객동기’(객체 → 동적 → 기능) 순서로 외운다."}},{"id":"written-2025-3-16","no":16,"unit":"소프트웨어 설계","q":"자료 흐름도(DFD)에서 각 요소와 표기 형태의 연결이 옳지 않은 것은?","choices":["Process : 원","Terminator : 사각형","Data Flow : 화살표","Data Store : 삼각형"],"ans":4,"exp":{"concept":"자료 흐름도(DFD, Data Flow Diagram)는 데이터가 시스템 안에서 어떻게 흐르고 처리되는지 그리는 도구다. 처리는 원, 자료 흐름은 화살표, 자료 저장소는 위아래 평행선(두 줄), 외부 단말은 사각형으로 그린다.","choices":[{"verdict":"오답","why":"처리(Process)는 원으로 표시하므로 옳은 연결이다."},{"verdict":"오답","why":"단말(Terminator)은 시스템 밖의 사람이나 기관을 뜻하며 사각형으로 표시하므로 옳은 연결이다."},{"verdict":"오답","why":"자료 흐름(Data Flow)은 화살표로 표시하므로 옳은 연결이다."},{"verdict":"정답","why":"자료 저장소(Data Store)는 삼각형이 아니라 위아래 평행선으로 표시하므로 옳지 않은 연결이다."}],"keywords":[{"term":"Process","desc":"처리, 원"},{"term":"Data Flow","desc":"자료 흐름, 화살표"},{"term":"Data Store","desc":"자료 저장소, 평행선(두 줄)"},{"term":"Terminator","desc":"단말(외부 개체), 사각형"}],"memo":"DFD 기호는 원·화살표·평행선·사각형 네 개뿐이다. 삼각형은 없다."}},{"id":"written-2025-3-17","no":17,"unit":"소프트웨어 설계","q":"요구사항 분석이 어려운 이유로 볼 수 없는 것은?","choices":["개발자와 사용자 사이의 지식이나 표현 차이가 커서 서로 이해하기가 쉽지 않다.","사용자의 요구사항이 모호하고 명확하지 않다.","사용자의 요구에는 예외가 거의 없어 열거와 구조화가 어렵지 않다.","소프트웨어 개발 과정 중에도 요구사항이 계속 바뀔 수 있다."],"ans":3,"exp":{"concept":"요구사항 분석이 어려운 까닭은 개발자와 사용자의 배경지식이 달라 의사소통이 어렵고, 사용자 요구가 모호하며, 개발 도중에도 요구가 바뀌고, 예외가 많아 정리하기 힘들기 때문이다.","choices":[{"verdict":"오답","why":"개발자와 사용자 사이의 지식·표현 차이는 요구사항 분석을 어렵게 하는 대표적인 이유다."},{"verdict":"오답","why":"사용자의 요구사항이 모호하고 불명확한 것도 분석을 어렵게 하는 이유다."},{"verdict":"정답","why":"실제로는 사용자 요구에 예외가 많아 열거하고 구조화하기 어렵다. 예외가 거의 없다는 설명은 사실과 반대이므로 어려운 이유가 될 수 없다."},{"verdict":"오답","why":"개발 과정 중에 요구사항이 계속 바뀌는 것도 분석을 어렵게 하는 이유다."}],"keywords":[{"term":"요구사항 분석의 어려움","desc":"의사소통 차이, 요구의 모호함, 잦은 변경, 많은 예외"},{"term":"요구사항 변경","desc":"개발 도중에도 요구가 바뀌어 관리가 필요함"}],"memo":"‘예외가 거의 없어 어렵지 않다’처럼 어려움을 부정하는 보기가 정답이 된다."}},{"id":"written-2025-3-18","no":18,"unit":"소프트웨어 설계","q":"소프트웨어 설계에서 쓰이는 대표적인 추상화(Abstraction) 기법에 해당하지 않는 것은?","choices":["강도 추상화","제어 추상화","자료 추상화","과정 추상화"],"ans":1,"exp":{"concept":"추상화(Abstraction)는 복잡한 것에서 핵심만 뽑아 단순하게 보는 방법이다. 소프트웨어 설계에서는 과정 추상화, 자료(데이터) 추상화, 제어 추상화 세 가지를 쓴다. 지도에서 모든 건물 대신 큰 길만 그리는 것과 비슷하다.","choices":[{"verdict":"정답","why":"강도 추상화는 소프트웨어 설계의 추상화 기법에 해당하지 않는다."},{"verdict":"오답","why":"제어 추상화는 제어의 정확한 메커니즘을 정의하지 않고 원하는 효과만 정하는 추상화 기법이다."},{"verdict":"오답","why":"자료 추상화는 데이터의 세부 구현은 감추고 데이터와 그 연산만 드러내는 추상화 기법이다."},{"verdict":"오답","why":"과정 추상화는 수행 과정의 자세한 단계 대신 전체 흐름만 정의하는 추상화 기법이다."}],"keywords":[{"term":"과정 추상화","desc":"자세한 수행 단계를 감추고 전체 흐름만 정의"},{"term":"자료 추상화","desc":"데이터 구조의 세부를 감추고 데이터와 연산만 표현"},{"term":"제어 추상화","desc":"제어 메커니즘의 세부 없이 원하는 효과만 정의"}],"memo":"추상화는 ‘과정·자료·제어’ 세 가지. 처음 보는 이름이 나오면 그것이 답이다."}},{"id":"written-2025-3-19","no":19,"unit":"소프트웨어 설계","q":"소프트웨어 공학의 모델링(Modeling)에 관한 설명 중 틀린 것은?","choices":["개발팀이 응용문제를 이해하는 데 도움이 될 수 있다.","절차적인 프로그램을 위한 자료 흐름도는 프로세스 위주의 모델링 방법에 해당한다.","모델링 기법은 유지보수 단계에서만 활용한다.","개발될 시스템에 대해 여러 분야의 엔지니어들이 공통된 개념을 공유하도록 돕는다."],"ans":3,"exp":{"concept":"모델링(Modeling)은 만들 시스템을 그림이나 기호로 단순하게 표현하는 일이다. 개발팀이 문제를 이해하고 여러 분야 엔지니어가 같은 그림을 보며 생각을 맞추게 해 준다. 분석·설계 단계부터 유지보수까지 개발 전 과정에서 활용된다.","choices":[{"verdict":"오답","why":"모델링은 개발팀이 응용 문제를 이해하는 데 도움을 준다."},{"verdict":"오답","why":"자료 흐름도(DFD)는 처리 과정을 중심으로 표현하므로 프로세스 위주의 모델링 방법에 해당한다."},{"verdict":"정답","why":"모델링 기법은 유지보수 단계에서만이 아니라 분석·설계 등 개발 전 단계에서 활용되므로 틀린 설명이다."},{"verdict":"오답","why":"모델링은 여러 분야의 엔지니어가 시스템에 대한 공통된 개념을 공유하도록 돕는다."}],"keywords":[{"term":"모델링(Modeling)","desc":"시스템을 그림·기호로 단순하게 표현해 이해와 소통을 돕는 활동"},{"term":"자료 흐름도(DFD)","desc":"데이터의 흐름과 처리를 중심으로 표현하는 구조적 분석 도구"}],"memo":"‘~에서만 활용한다’는 표현이 붙은 보기를 먼저 의심한다."}},{"id":"written-2025-3-20","no":20,"unit":"소프트웨어 설계","q":"객체지향 분석 방법론 가운데 Jacobson 방법에 해당하는 것은?","choices":["E-R 다이어그램을 사용해 객체의 행위를 데이터 모델링하는 데 초점을 두는 방법이다.","Use-Case를 강조해 사용하는 방법이다.","객체, 동적, 기능 모델로 나누어 수행하는 방법이다.","미시적 개발 프로세스와 거시적 개발 프로세스를 모두 사용하는 방법이다."],"ans":2,"exp":{"concept":"객체지향 분석 방법론은 만든 사람마다 특징이 다르다. 제이콥슨(Jacobson)은 사용자가 시스템을 어떻게 쓰는지 나타내는 유스케이스(Use Case)를 강조한다. 럼바우는 객체·동적·기능 모델, 부치는 미시적·거시적 개발 프로세스, 코드-요돈은 E-R 다이어그램을 쓴다.","choices":[{"verdict":"오답","why":"E-R 다이어그램으로 객체의 행위를 데이터 모델링하는 데 초점을 둔 것은 코드와 요돈(Coad-Yourdon) 방법이다."},{"verdict":"정답","why":"유스케이스를 강조해 사용하는 것이 제이콥슨(Jacobson) 방법이므로 정답이다."},{"verdict":"오답","why":"객체, 동적, 기능 모델로 나누어 수행하는 것은 럼바우(Rumbaugh) 방법이다."},{"verdict":"오답","why":"미시적·거시적 개발 프로세스를 모두 사용하는 것은 부치(Booch) 방법이다."}],"keywords":[{"term":"Jacobson","desc":"유스케이스 중심 분석"},{"term":"Rumbaugh","desc":"객체·동적·기능 모델링(OMT)"},{"term":"Booch","desc":"미시적·거시적 개발 프로세스"},{"term":"Coad-Yourdon","desc":"E-R 다이어그램으로 객체 행위 모델링"}],"memo":"제이콥슨은 유스케이스, 럼바우는 세 모델, 부치는 미시·거시로 짝지어 외운다."}},{"id":"written-2025-3-21","no":21,"unit":"소프트웨어 개발","q":"제품 소프트웨어 패키징 도구를 활용할 때 고려사항으로 볼 수 없는 것은?","choices":["추가적으로 다양한 이기종 연동을 고려한다.","내부 콘텐츠에 대한 보안은 고려 대상에 두지 않는다.","사용자 편의성을 위해 복잡성 및 비효율성 문제를 고려한다.","제품 소프트웨어의 종류에 알맞은 암호화 알고리즘을 고려한다."],"ans":2,"exp":{"concept":"제품 소프트웨어 패키징 도구는 완성된 소프트웨어를 배포용으로 묶으면서 불법 복제를 막는 암호화·보안 기능을 적용한다. 그래서 내부 콘텐츠의 암호화와 보안은 반드시 고려해야 하고, 이기종 연동, 사용자 편의성, 알맞은 암호화 알고리즘도 함께 고려한다.","choices":[{"verdict":"오답","why":"패키징 도구는 다양한 기종·콘텐츠와의 연동을 추가로 고려해야 한다."},{"verdict":"정답","why":"패키징 도구를 쓸 때는 내부 콘텐츠의 암호화와 보안을 반드시 고려해야 한다. 고려 대상에서 뺀다는 설명은 틀렸다."},{"verdict":"오답","why":"보안을 강화하면서 생기는 복잡성과 비효율로 사용자 편의성이 떨어지지 않도록 고려해야 한다."},{"verdict":"오답","why":"제품 소프트웨어의 종류에 맞는 암호화 알고리즘을 선택해 적용해야 한다."}],"keywords":[{"term":"패키징 도구","desc":"배포용 패키지를 만들면서 암호화·보안 기능을 적용하는 도구"},{"term":"패키징 도구 고려사항","desc":"반드시 내부 콘텐츠 암호화·보안, 이기종 연동, 사용자 편의성, 적합한 암호화 알고리즘"}],"memo":"패키징 도구 문제에서 ‘보안을 고려하지 않는다’는 보기는 항상 틀렸다."}},{"id":"written-2025-3-22","no":22,"unit":"소프트웨어 개발","q":"스택에 관한 설명 중 틀린 것은?","choices":["더 이상 삭제할 데이터가 없는 상태에서 데이터를 삭제하려 하면 언더플로(Underflow)가 발생한다.","Head(front)와 Tail(rear)의 2개 포인터를 가지고 있다.","LIFO 구조이다.","입출력이 한쪽 끝으로만 제한되는 리스트이다."],"ans":2,"exp":{"concept":"스택(Stack)은 한쪽 끝(Top)으로만 넣고 빼는 자료 구조로, 나중에 넣은 것이 먼저 나오는 LIFO(Last In First Out) 구조다. 접시를 쌓아 두고 맨 위에서만 꺼내는 것과 같다. 포인터는 맨 위를 가리키는 Top 하나만 있다.","choices":[{"verdict":"오답","why":"비어 있는 스택에서 삭제하려 하면 언더플로(Underflow)가 발생한다. 반대로 가득 찬 스택에 넣으면 오버플로(Overflow)다."},{"verdict":"정답","why":"Front와 Rear 두 포인터를 갖는 것은 큐(Queue)다. 스택은 Top 포인터 하나만 쓰므로 틀린 설명이다."},{"verdict":"오답","why":"스택은 나중에 들어간 데이터가 먼저 나오는 LIFO 구조다."},{"verdict":"오답","why":"스택은 삽입과 삭제가 Top이라는 한쪽 끝에서만 이루어지는 리스트다."}],"keywords":[{"term":"스택(Stack)","desc":"LIFO, Top 하나로 삽입·삭제"},{"term":"큐(Queue)","desc":"FIFO, Front에서 삭제하고 Rear에서 삽입"},{"term":"언더플로(Underflow)","desc":"빈 스택에서 삭제를 시도할 때 발생"}],"memo":"포인터가 두 개(Front, Rear)면 큐, 하나(Top)면 스택이다."}},{"id":"written-2025-3-23","no":23,"unit":"소프트웨어 개발","q":"다음 중 EAI(Enterprise Application Integration)의 구축 유형에 해당하지 않는 것은?","choices":["Tree","Point-to-Point","Hub &amp; Spoke","Message Bus"],"ans":1,"exp":{"concept":"EAI(Enterprise Application Integration)는 기업 안의 여러 애플리케이션을 연결해 데이터와 업무를 통합하는 솔루션이다. 구축 유형은 Point-to-Point, Hub & Spoke, Message Bus, Hybrid 네 가지다.","choices":[{"verdict":"정답","why":"Tree는 EAI 구축 유형에 해당하지 않는다."},{"verdict":"오답","why":"Point-to-Point는 애플리케이션끼리 1:1로 직접 연결하는 가장 기본적인 EAI 유형이다."},{"verdict":"오답","why":"Hub & Spoke는 가운데 허브를 두고 모든 애플리케이션이 허브를 거쳐 통신하는 EAI 유형이다."},{"verdict":"오답","why":"Message Bus는 애플리케이션 사이에 미들웨어(버스)를 두어 처리하는 EAI 유형이다."}],"keywords":[{"term":"Point-to-Point","desc":"1:1 직접 연결, 변경과 재사용이 어려움"},{"term":"Hub & Spoke","desc":"중앙 허브를 통한 연결, 허브 장애 시 전체 영향"},{"term":"Message Bus","desc":"애플리케이션 사이에 미들웨어 버스를 둠, 확장성 우수"},{"term":"Hybrid","desc":"그룹 내는 Hub & Spoke, 그룹 간은 Message Bus"}],"memo":"EAI 유형은 ‘포허메하’(Point-to-Point, Hub & Spoke, Message Bus, Hybrid). 트리(Tree)는 없다."}},{"id":"written-2025-3-24","no":24,"unit":"소프트웨어 개발","q":"다음 트리를 Preorder 운행법으로 운행하면 가장 먼저 탐색되는 노드는?<img class=\"q-img\" src=\"data/img/117638ff1825dcb0795e339712b8a459.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["G","B","D","A"],"ans":4,"exp":{"concept":"전위 운행(Preorder)은 루트 → 왼쪽 서브트리 → 오른쪽 서브트리 순서로 방문한다. 루트를 가장 먼저 방문하므로 어떤 트리든 처음 탐색되는 노드는 루트다. 그림의 트리는 A가 루트이고 왼쪽에 B(그 아래 D), 오른쪽에 C(그 아래 E, F, E 아래 G, H)가 있다.","choices":[{"verdict":"오답","why":"G는 E의 왼쪽 자식으로, 전위 운행에서는 A, B, D, C, E 다음 여섯 번째로 방문된다."},{"verdict":"오답","why":"B는 루트 A 다음, 두 번째로 방문된다."},{"verdict":"오답","why":"D는 A, B 다음 세 번째로 방문된다."},{"verdict":"정답","why":"전위 운행은 루트를 가장 먼저 방문하므로 루트인 A가 처음 탐색된다. 전체 순서는 A, B, D, C, E, G, H, F다."}],"keywords":[{"term":"전위 운행(Preorder)","desc":"Root → Left → Right"},{"term":"중위 운행(Inorder)","desc":"Left → Root → Right"},{"term":"후위 운행(Postorder)","desc":"Left → Right → Root"}],"memo":"전위·중위·후위는 루트를 언제 방문하느냐(앞·가운데·뒤)로 구분한다. 전위의 첫 노드는 언제나 루트다."}},{"id":"written-2025-3-25","no":25,"unit":"소프트웨어 개발","q":"클린 코드 작성 원칙에 관한 설명으로 옳지 않은 것은?","choices":["코드는 간단하게 작성한다.","누구나 코드를 쉽게 읽을 수 있게 작성한다.","코드의 중복은 최소화한다.","다른 모듈에 코드가 미치는 영향을 최대화하도록 작성한다."],"ans":4,"exp":{"concept":"클린 코드(Clean Code)는 누구나 쉽게 읽고 고칠 수 있게 깔끔하게 작성한 코드다. 가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화가 작성 원칙이다. 한 모듈을 고쳤을 때 다른 모듈이 흔들리지 않도록 영향을 최소화해야 한다.","choices":[{"verdict":"오답","why":"코드를 간단하게 작성하는 것은 단순성 원칙에 맞다."},{"verdict":"오답","why":"누구나 쉽게 읽을 수 있게 작성하는 것은 가독성 원칙에 맞다."},{"verdict":"오답","why":"코드 중복을 최소화하는 것은 중복성 최소화 원칙에 맞다."},{"verdict":"정답","why":"다른 모듈에 미치는 영향은 최대화가 아니라 최소화해야 한다(의존성 배제). 따라서 옳지 않다."}],"keywords":[{"term":"가독성","desc":"누구나 쉽게 읽을 수 있게 작성"},{"term":"단순성","desc":"한 번에 한 가지를 처리하도록 간단하게 작성"},{"term":"의존성 배제","desc":"다른 모듈에 미치는 영향을 최소화"},{"term":"중복성 최소화","desc":"코드 중복을 줄임"}],"memo":"클린 코드 원칙은 ‘가단의중추’(가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화)."}},{"id":"written-2025-3-26","no":26,"unit":"소프트웨어 개발","q":"소프트웨어 형상 관리가 의미하는 것으로 적절한 것은?","choices":["개발 과정에서의 변경 사항을 관리하는 것","테스트 과정에서 소프트웨어를 통합하는 것","개발 인력을 관리하는 것","비용에 관한 사항을 효율적으로 관리하는 것"],"ans":1,"exp":{"concept":"소프트웨어 형상 관리(SCM, Software Configuration Management)는 개발 과정에서 생기는 소스 코드, 문서 등의 변경 사항을 체계적으로 추적하고 통제하는 활동이다. 누가 언제 무엇을 바꿨는지 기록해 두는 일이다.","choices":[{"verdict":"정답","why":"형상 관리는 개발 과정에서 발생하는 변경 사항을 관리하는 것이므로 정답이다."},{"verdict":"오답","why":"테스트 과정에서 소프트웨어를 통합하는 것은 통합 테스트에 관한 설명이다."},{"verdict":"오답","why":"개발 인력을 관리하는 것은 프로젝트 관리 중 인력 관리에 해당한다."},{"verdict":"오답","why":"비용을 관리하는 것은 프로젝트 관리 중 비용 관리에 해당한다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"개발 중 변경 사항을 식별·통제·기록하는 활동"},{"term":"형상 관리 절차","desc":"형상 식별 → 형상 통제 → 형상 감사 → 형상 기록"},{"term":"형상 관리 도구","desc":"Git, SVN, CVS 등"}],"memo":"형상 관리 = 변경 관리. ‘변경’이라는 단어를 찾으면 된다."}},{"id":"written-2025-3-27","no":27,"unit":"소프트웨어 개발","q":"정형 기술 검토(FTR)의 지침으로 옳지 않은 것은?","choices":["논쟁과 반박은 제한한다.","의제를 제한하도록 한다.","문제 영역을 명확하게 표현한다.","참가자의 수는 제한하지 않는다."],"ans":4,"exp":{"concept":"정형 기술 검토(FTR, Formal Technical Review)는 소프트웨어 산출물을 여러 사람이 공식적으로 함께 검토해 오류를 찾는 활동이다. 효율적인 회의를 위해 의제와 참가자 수를 제한하고, 논쟁과 반박도 제한하며, 문제 영역을 명확히 표현해야 한다.","choices":[{"verdict":"오답","why":"논쟁과 반박을 제한하는 것은 FTR 지침에 맞다."},{"verdict":"오답","why":"의제를 제한하는 것은 FTR 지침에 맞다."},{"verdict":"오답","why":"문제 영역을 명확하게 표현하는 것은 FTR 지침에 맞다."},{"verdict":"정답","why":"FTR에서는 참가자 수를 제한해야 한다. 제한하지 않는다는 설명은 지침에 어긋난다."}],"keywords":[{"term":"정형 기술 검토(FTR)","desc":"산출물을 공식적으로 검토해 오류를 찾는 품질 보증 활동"},{"term":"FTR 지침","desc":"제품 검토에 집중, 의제·참가자 수 제한, 논쟁·반박 제한, 사전 준비, 체크리스트 사용"},{"term":"인스펙션(Inspection)","desc":"FTR의 한 유형으로, 전문가가 산출물을 단계적으로 정밀 검사하는 기법"}],"memo":"FTR 지침은 ‘제한’이 핵심이다. 의제·참가자·논쟁 모두 제한한다."}},{"id":"written-2025-3-28","no":28,"unit":"소프트웨어 개발","q":"인터페이스 간 통신에 이용되는 데이터 포맷에 해당하지 않는 것은?","choices":["YAML","JSON","XML","AJTML"],"ans":4,"exp":{"concept":"인터페이스로 시스템끼리 데이터를 주고받을 때는 서로 약속된 형식(데이터 포맷)을 쓴다. 대표적으로 JSON, XML, YAML, CSV 등이 있다.","choices":[{"verdict":"오답","why":"YAML은 들여쓰기로 구조를 표현해 사람이 읽기 쉬운 데이터 직렬화 형식이다."},{"verdict":"오답","why":"JSON(JavaScript Object Notation)은 속성-값 쌍으로 이루어진 가벼운 데이터 교환 형식이다."},{"verdict":"오답","why":"XML(eXtensible Markup Language)은 태그로 데이터 구조를 정의하는 마크업 언어로, 데이터 교환에 쓰인다."},{"verdict":"정답","why":"AJTML은 데이터 포맷이 아니며 출제 범위의 표준 용어가 아니다. 비슷한 이름의 AJAX는 비동기 통신 기술이다."}],"keywords":[{"term":"JSON","desc":"속성-값 쌍으로 표현하는 가벼운 데이터 교환 형식"},{"term":"XML","desc":"태그 기반의 확장 가능한 마크업 언어"},{"term":"YAML","desc":"들여쓰기 기반의 읽기 쉬운 데이터 형식"},{"term":"AJAX","desc":"페이지 전체를 새로 고치지 않고 서버와 비동기로 데이터를 주고받는 기술"}],"memo":"데이터 포맷은 JSON, XML, YAML, CSV. 이상한 철자의 이름은 만들어 낸 오답이다."}},{"id":"written-2025-3-29","no":29,"unit":"소프트웨어 개발","q":"저작권 관리 구성 요소에 관한 설명으로 옳지 않은 것은?","choices":["DRM 컨트롤러 : 배포된 콘텐츠의 이용 권한을 통제하는 역할","콘텐츠 제공자(Contents Provider) : 콘텐츠를 제공하는 저작권자","콘텐츠 분배자(Contents Distributor) : 메타 데이터와 함께 콘텐츠를 배포 가능한 단위로 묶는 기능","클리어링 하우스(Clearing House) : 키 관리와 라이선스 발급 관리"],"ans":3,"exp":{"concept":"디지털 저작권 관리(DRM)는 여러 구성 요소가 역할을 나눈다. 콘텐츠 제공자는 저작권자, 패키저(Packager)는 콘텐츠를 메타데이터와 함께 배포 가능한 단위로 묶는 역할, 콘텐츠 분배자는 암호화된 콘텐츠를 유통하는 곳, 클리어링 하우스는 키 관리와 라이선스 발급을 맡는다.","choices":[{"verdict":"오답","why":"DRM 컨트롤러는 배포된 콘텐츠의 이용 권한을 통제한다."},{"verdict":"오답","why":"콘텐츠 제공자(Contents Provider)는 콘텐츠를 제공하는 저작권자다."},{"verdict":"정답","why":"메타데이터와 함께 배포 가능한 단위로 묶는 것은 패키저(Packager)의 역할이다. 콘텐츠 분배자(Contents Distributor)는 쇼핑몰처럼 암호화된 콘텐츠를 유통하는 곳이다."},{"verdict":"오답","why":"클리어링 하우스(Clearing House)는 저작권 사용 권한, 키 관리, 라이선스 발급, 사용량에 따른 결제를 관리한다."}],"keywords":[{"term":"패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 배포 가능한 단위로 묶음"},{"term":"콘텐츠 분배자","desc":"암호화된 콘텐츠를 유통하는 곳이나 사람"},{"term":"클리어링 하우스","desc":"키 관리, 라이선스 발급, 사용량 결제 관리"},{"term":"보안 컨테이너","desc":"콘텐츠를 안전하게 유통하기 위한 전자적 보안 장치"}],"memo":"‘묶는다(패키지)’는 패키저, ‘유통한다(분배)’는 분배자. 이름 그대로의 뜻을 떠올린다."}},{"id":"written-2025-3-30","no":30,"unit":"소프트웨어 개발","q":"소프트웨어 설치 매뉴얼에 관한 설명 중 틀린 것은?","choices":["설치를 시작해서 완료할 때까지의 전 과정을 순서대로 빠짐없이 설명한다.","설치 과정에서 표시될 수 있는 예외상황과 관련된 내용은 별도로 구분하여 설명한다.","설치 매뉴얼에는 목차, 개요, 기본사항 등이 기본적으로 포함되어야 한다.","설치 매뉴얼은 개발자를 기준으로 작성한다."],"ans":4,"exp":{"concept":"소프트웨어 설치 매뉴얼은 사용자가 설치를 처음부터 끝까지 따라 할 수 있도록 안내하는 문서다. 따라서 개발자가 아니라 사용자 기준으로 작성하며, 설치 전 과정을 순서대로 빠짐없이 설명하고 예외 상황은 따로 구분해 설명한다.","choices":[{"verdict":"오답","why":"설치 시작부터 완료까지 전 과정을 순서대로 빠짐없이 설명해야 한다."},{"verdict":"오답","why":"설치 중 나타날 수 있는 예외 상황은 별도로 구분해 설명한다."},{"verdict":"오답","why":"설치 매뉴얼에는 목차, 개요, 기본 사항 등이 기본으로 포함된다."},{"verdict":"정답","why":"설치 매뉴얼은 개발자가 아니라 사용자를 기준으로 작성한다. 따라서 틀린 설명이다."}],"keywords":[{"term":"설치 매뉴얼","desc":"사용자 기준으로 설치 과정을 순서대로 안내하는 문서"},{"term":"설치 매뉴얼 기본 구성","desc":"목차, 개요, 기본 사항(문서 이력, 설치 도구 구성 등)"}],"memo":"매뉴얼은 읽는 사람(사용자) 기준이다. ‘개발자 기준’이면 틀렸다."}},{"id":"written-2025-3-31","no":31,"unit":"소프트웨어 개발","q":"입력 순서가 A, B, C, D로 정해진 자료를 스택에 넣은 뒤 출력했을 때 나올 수 없는 결과는?","choices":["B, C, D, A","D, C, B, A","D, B, C, A","C, B, A, D"],"ans":3,"exp":{"concept":"스택은 나중에 넣은 것이 먼저 나오는 LIFO 구조다. 입력 순서가 A, B, C, D로 정해져 있어도 중간중간 꺼낼 수 있으므로 여러 출력 순서가 나올 수 있다. 다만 어떤 값을 꺼낸 순간 스택에 남아 있는 값들은 넣은 역순으로만 나올 수 있다.","choices":[{"verdict":"오답","why":"A, B를 넣고 B를 꺼낸 뒤 C를 넣고 꺼내고, D를 넣고 꺼낸 다음 마지막에 A를 꺼내면 B, C, D, A가 나온다."},{"verdict":"오답","why":"A, B, C, D를 모두 넣은 뒤 차례로 꺼내면 D, C, B, A가 나온다."},{"verdict":"정답","why":"D를 먼저 꺼내려면 A, B, C, D를 모두 넣어야 하고, 이때 스택은 아래부터 A, B, C다. 맨 위가 C이므로 다음에는 C가 나와야 하며 B가 먼저 나올 수 없다. 따라서 불가능한 순서다."},{"verdict":"오답","why":"A, B, C를 넣고 C, B, A 순으로 꺼낸 뒤 D를 넣고 꺼내면 C, B, A, D가 나온다."}],"keywords":[{"term":"LIFO","desc":"Last In First Out, 나중에 넣은 것이 먼저 나옴"},{"term":"Push / Pop","desc":"스택에 넣기 / 스택에서 꺼내기"},{"term":"Top","desc":"스택의 맨 위를 가리키는 포인터"}],"memo":"어떤 값이 나온 뒤, 그보다 먼저 들어간 값들은 반드시 역순으로 나와야 한다. D 다음에 B, C처럼 오름차순이 섞이면 불가능하다."}},{"id":"written-2025-3-32","no":32,"unit":"소프트웨어 개발","q":"알파 테스트 및 베타 테스트와 가장 밀접하게 관련된 테스트 단계는?","choices":["통합 테스트","인수 테스트","시스템 테스트","단위 테스트"],"ans":2,"exp":{"concept":"인수 테스트는 개발이 끝난 소프트웨어를 사용자가 직접 확인해 받아들일지 결정하는 마지막 테스트 단계다. 알파 테스트는 개발자 장소에서 사용자가 개발자와 함께, 베타 테스트는 사용자 장소에서 개발자 없이 실제 환경으로 진행하는 인수 테스트다.","choices":[{"verdict":"오답","why":"통합 테스트는 단위 테스트를 마친 모듈들을 결합하면서 인터페이스 오류를 찾는 테스트다."},{"verdict":"정답","why":"알파·베타 테스트는 사용자가 참여하는 인수 테스트의 종류이므로 정답이다."},{"verdict":"오답","why":"시스템 테스트는 통합된 시스템 전체가 요구사항대로 동작하는지 개발 조직이 검증하는 테스트다."},{"verdict":"오답","why":"단위 테스트는 모듈이나 컴포넌트 하나하나를 개별적으로 검사하는 테스트다."}],"keywords":[{"term":"알파 테스트","desc":"개발자 장소에서 사용자가 개발자 앞에서 하는 통제된 환경의 테스트"},{"term":"베타 테스트","desc":"실제 사용자 환경에서 개발자 없이 하는 테스트"},{"term":"인수 테스트","desc":"사용자 요구 충족 여부를 사용자가 확인하는 최종 단계 테스트"}],"memo":"V 모델 순서는 단위 → 통합 → 시스템 → 인수. 사용자가 등장하는 알파·베타는 마지막 인수 테스트다."}},{"id":"written-2025-3-33","no":33,"unit":"소프트웨어 개발","q":"인터페이스 보안을 위해 네트워크 영역에 적용할 수 있는 솔루션과 가장 거리가 먼 것은?","choices":["S-HTTP","IPSec","SMTP","SSL"],"ans":3,"exp":{"concept":"인터페이스 보안은 시스템끼리 주고받는 데이터가 도청·변조되지 않도록 보호하는 것이다. 네트워크 영역에서는 IPSec, SSL/TLS, S-HTTP처럼 전송 구간을 암호화하는 프로토콜을 적용한다.","choices":[{"verdict":"오답","why":"S-HTTP(Secure HTTP)는 웹에서 클라이언트와 서버 사이의 메시지를 암호화하는 보안 프로토콜이다."},{"verdict":"오답","why":"IPSec은 네트워크 계층(IP)에서 패킷을 암호화·인증하는 보안 프로토콜이다."},{"verdict":"정답","why":"SMTP(Simple Mail Transfer Protocol)는 전자우편을 전송하는 프로토콜로, 보안 솔루션이 아니다."},{"verdict":"오답","why":"SSL(Secure Sockets Layer)은 전송 계층 위에서 데이터를 암호화하는 보안 프로토콜이다."}],"keywords":[{"term":"IPSec","desc":"IP 계층에서 패킷 암호화·인증"},{"term":"SSL/TLS","desc":"전송 계층 위에서 통신 구간 암호화"},{"term":"S-HTTP","desc":"웹 메시지 단위 암호화"},{"term":"SMTP","desc":"전자우편 전송 프로토콜"}],"memo":"이름에 S(Secure)나 Sec이 들어간 것이 보안 프로토콜이다. SMTP의 S는 Simple이다."}},{"id":"written-2025-3-34","no":34,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM)에서 사용되는 기술 요소에 해당하지 않는 것은?","choices":["암호화","방화벽","크랙방지","키 관리"],"ans":2,"exp":{"concept":"디지털 저작권 관리(DRM, Digital Rights Management)는 디지털 콘텐츠가 허락된 사람에게만 허락된 만큼 쓰이도록 보호하는 기술이다. 기술 요소로 암호화, 키 관리, 암호화 파일 생성, 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증이 있다.","choices":[{"verdict":"오답","why":"암호화는 콘텐츠와 라이선스를 암호화하고 전자 서명하는 DRM 기술 요소다."},{"verdict":"정답","why":"방화벽은 네트워크 경계에서 허가되지 않은 트래픽을 막는 네트워크 보안 장비로, DRM 기술 요소가 아니다."},{"verdict":"오답","why":"크랙 방지는 크랙을 이용한 콘텐츠 무단 사용을 막는 DRM 기술 요소다."},{"verdict":"오답","why":"키 관리는 콘텐츠를 암호화한 키를 저장하고 분배하는 DRM 기술 요소다."}],"keywords":[{"term":"DRM 기술 요소","desc":"암호화, 키 관리, 암호화 파일 생성, 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증"},{"term":"방화벽(Firewall)","desc":"내부 네트워크로 들어오고 나가는 트래픽을 규칙에 따라 통제하는 장비"}],"memo":"DRM은 콘텐츠 자체를 지키는 기술이고, 방화벽은 네트워크를 지키는 장비다."}},{"id":"written-2025-3-35","no":35,"unit":"소프트웨어 개발","q":"개발자 관점에서 소프트웨어 품질 측정을 위해 고려해야 할 항목과 거리가 먼 것은?","choices":["간결성","정확성","사용성","무결성"],"ans":1,"exp":{"concept":"개발자 관점에서 소프트웨어 품질을 잴 때는 정확성, 신뢰성, 효율성, 무결성, 사용 용이성(사용성), 유지보수성, 유연성, 시험 역량, 이식성, 재사용성, 상호 운용성 같은 항목을 고려한다. 간결성은 이 품질 측정 항목에 들어가지 않는다.","choices":[{"verdict":"정답","why":"간결성은 개발자 관점의 소프트웨어 품질 측정 항목에 해당하지 않는다."},{"verdict":"오답","why":"정확성은 사용자의 요구 기능을 정확히 충족하는 정도로, 품질 측정 항목이다."},{"verdict":"오답","why":"사용성(사용 용이성)은 사용자가 쉽게 배우고 사용할 수 있는 정도로, 품질 측정 항목이다."},{"verdict":"오답","why":"무결성은 허용되지 않은 사용이나 자료 변경을 막는 정도로, 품질 측정 항목이다."}],"keywords":[{"term":"정확성","desc":"요구된 기능을 정확히 수행하는 정도"},{"term":"무결성","desc":"허가되지 않은 접근·변경을 통제하는 정도"},{"term":"사용 용이성","desc":"사용자가 쉽게 배우고 사용하는 정도"},{"term":"신뢰성","desc":"정해진 기능을 오류 없이 수행하는 정도"}],"memo":"‘간결’, ‘단순’처럼 코드 스타일을 말하는 단어는 품질 측정 항목이 아니다."}},{"id":"written-2025-3-36","no":36,"unit":"소프트웨어 개발","q":"프로젝트에 내재된 위험 요소를 인식하고 그 영향을 분석해 관리하는 활동으로, 프로젝트를 성공시키기 위해 위험 요소를 미리 예측하고 대비하는 모든 기술과 활동을 포함하는 것은?","choices":["Work Breakdown Structure","Waterfall Model","Risk Analysis","Critical Path Method"],"ans":3,"exp":{"concept":"위험 분석(Risk Analysis)은 프로젝트에 숨어 있는 위험 요소를 미리 찾아내고, 그 영향을 분석해 대비하는 활동이다. 비가 올지 미리 예보를 보고 우산을 챙기는 것과 같다.","choices":[{"verdict":"오답","why":"WBS(Work Breakdown Structure)는 프로젝트 작업을 작은 단위로 계층적으로 나눈 작업 분할 구조다."},{"verdict":"오답","why":"폭포수 모형(Waterfall Model)은 개발 단계를 순서대로 한 단계씩 진행하는 개발 모형이다."},{"verdict":"정답","why":"위험 분석(Risk Analysis)은 위험 요소를 인식하고 영향을 분석해 관리하는 활동이므로 정답이다."},{"verdict":"오답","why":"CPM(Critical Path Method)은 작업 순서와 소요 기간으로 프로젝트의 임계 경로를 찾는 일정 관리 기법이다."}],"keywords":[{"term":"위험 분석(Risk Analysis)","desc":"위험 요소를 예측·분석하고 대비하는 활동"},{"term":"WBS","desc":"프로젝트 작업을 계층적으로 분할한 구조"},{"term":"CPM","desc":"임계 경로를 찾아 일정을 관리하는 기법"}],"memo":"‘위험 요소’라는 말이 나오면 Risk가 들어간 보기를 고른다."}},{"id":"written-2025-3-37","no":37,"unit":"소프트웨어 개발","q":"버전 관리 항목 가운데 저장소를 새로운 버전의 파일로 갱신하는 것을 뜻하는 용어는?","choices":["체크인(Check-In)","형상 감사(Configuration Audit)","롤백 (Rollback)","단위 테스트(Unit Test)"],"ans":1,"exp":{"concept":"버전 관리에서 체크인(Check-In)은 수정한 파일을 저장소에 올려 새 버전으로 갱신하는 일이다. 반대로 체크아웃(Check-Out)은 저장소에서 파일을 받아 오는 일이다.","choices":[{"verdict":"정답","why":"체크인(Check-In)은 저장소의 파일을 새로운 버전으로 갱신하는 것이므로 정답이다."},{"verdict":"오답","why":"형상 감사(Configuration Audit)는 기준선의 무결성과 변경 사항이 제대로 반영되었는지 검토·평가하는 형상 관리 활동이다."},{"verdict":"오답","why":"롤백(Rollback)은 작업을 취소하고 이전 상태로 되돌리는 것이다."},{"verdict":"오답","why":"단위 테스트(Unit Test)는 모듈 하나를 개별적으로 검사하는 테스트로, 버전 관리 용어가 아니다."}],"keywords":[{"term":"체크인(Check-In)","desc":"수정한 파일을 저장소에 반영해 새 버전으로 갱신"},{"term":"체크아웃(Check-Out)","desc":"저장소에서 파일을 받아 옴"},{"term":"커밋(Commit)","desc":"변경 내용을 저장소에 확정"},{"term":"저장소(Repository)","desc":"최신 버전 파일과 변경 이력을 보관하는 곳"}],"memo":"도서관처럼 생각한다. 책을 반납(Check-In)하면 서가가 갱신되고, 빌리면(Check-Out) 가져온다."}},{"id":"written-2025-3-38","no":38,"unit":"소프트웨어 개발","q":"정렬된 N개의 데이터를 처리할 때 \\(O(N\\log_2 N)\\)의 시간이 걸리는 정렬 알고리즘은?","choices":["선택 정렬","합병 정렬","버블 정렬","삽입 정렬"],"ans":2,"exp":{"concept":"정렬 알고리즘마다 걸리는 시간이 다르다. 합병 정렬(Merge Sort)은 데이터를 반으로 계속 나눈 뒤 합치며 정렬하므로 나누는 단계가 log₂N번, 각 단계의 합병에 N번이 들어 입력 상태와 상관없이 O(N log₂ N)이다. 선택·버블·삽입 정렬은 평균과 최악이 O(N²)다.","choices":[{"verdict":"오답","why":"선택 정렬은 데이터가 정렬되어 있어도 매번 최솟값을 찾으므로 O(N²)이다."},{"verdict":"정답","why":"합병 정렬은 항상 O(N log₂ N)이므로 정답이다."},{"verdict":"오답","why":"버블 정렬은 인접한 두 값을 비교·교환하는 방식으로 평균·최악 O(N²)이다."},{"verdict":"오답","why":"삽입 정렬은 평균·최악 O(N²)이며, 이미 정렬된 데이터에서는 비교만 한 번씩 하므로 O(N)이다."}],"keywords":[{"term":"합병 정렬(Merge Sort)","desc":"분할 후 합병, 항상 O(N log N)"},{"term":"퀵 정렬(Quick Sort)","desc":"평균 O(N log N), 최악 O(N²)"},{"term":"힙 정렬(Heap Sort)","desc":"항상 O(N log N)"},{"term":"선택·버블·삽입 정렬","desc":"평균·최악 O(N²)"}],"memo":"N log N은 ‘쪼개는’ 정렬(합병, 퀵, 힙)이고, 이중 반복문으로 비교하는 정렬(선택, 버블, 삽입)은 N²이다."}},{"id":"written-2025-3-39","no":39,"unit":"소프트웨어 개발","q":"다음 중 블랙박스 검사 기법에 해당하는 것은?","choices":["경계값 분석","조건 검사","루프 검사","기초 경로 검사"],"ans":1,"exp":{"concept":"블랙박스 검사는 프로그램 내부를 보지 않고 입력과 출력만으로 기능이 맞는지 확인한다. 동치 분할, 경계값 분석, 원인-결과 그래프, 오류 예측, 비교 검사 등이 있다. 화이트박스 검사는 코드 내부 구조를 보며 조건, 루프, 경로를 검사한다.","choices":[{"verdict":"정답","why":"경계값 분석(Boundary Value Analysis)은 입력 범위의 경계에서 오류가 잘 난다는 점을 이용한 블랙박스 검사 기법이다."},{"verdict":"오답","why":"조건 검사(Condition Testing)는 프로그램 안의 논리 조건을 검사하는 화이트박스 검사 기법이다."},{"verdict":"오답","why":"루프 검사(Loop Testing)는 반복 구조를 중점적으로 검사하는 화이트박스 검사 기법이다."},{"verdict":"오답","why":"기초 경로 검사(Basis Path Testing)는 제어 흐름 그래프로 실행 경로를 검사하는 화이트박스 검사 기법이다."}],"keywords":[{"term":"블랙박스 검사","desc":"동치 분할, 경계값 분석, 원인-결과 그래프, 오류 예측, 비교 검사"},{"term":"화이트박스 검사","desc":"기초 경로, 조건, 루프, 데이터 흐름 검사"},{"term":"경계값 분석","desc":"입력 범위의 경계값을 중점적으로 테스트"}],"memo":"‘경로·조건·루프’처럼 코드 안을 들여다봐야 하는 단어는 화이트박스, ‘값·입력’ 중심은 블랙박스다."}},{"id":"written-2025-3-40","no":40,"unit":"소프트웨어 개발","q":"테스트 케이스 자동 생성 도구를 활용해 테스트 데이터를 찾아내는 방법에 해당하지 않는 것은?","choices":["입력 도메인 분석","랜덤(Random) 테스트","자료 흐름도","스터브(Stub)와 드라이버(Driver)"],"ans":4,"exp":{"concept":"테스트 케이스 자동 생성 도구는 테스트 데이터를 자동으로 찾아 준다. 자료 흐름도, 기능 테스트, 입력 도메인 분석, 랜덤 테스트 같은 방법을 쓴다. 스터브와 드라이버는 테스트 데이터를 찾는 방법이 아니라 통합 테스트에서 없는 모듈을 대신하는 임시 프로그램이다.","choices":[{"verdict":"오답","why":"입력 도메인 분석은 입력 변수가 가질 수 있는 값의 범위를 분석해 테스트 데이터를 찾는 방법이다."},{"verdict":"오답","why":"랜덤 테스트는 무작위로 값을 입력해 테스트 데이터를 찾는 방법이다."},{"verdict":"오답","why":"자료 흐름도를 이용해 테스트 경로와 데이터를 찾는 것도 테스트 데이터 생성 방법이다."},{"verdict":"정답","why":"스터브(Stub)와 드라이버(Driver)는 통합 테스트에서 아직 없는 하위·상위 모듈을 대신하는 임시 모듈이므로 테스트 데이터를 찾는 방법이 아니다."}],"keywords":[{"term":"스터브(Stub)","desc":"하향식 통합 테스트에서 하위 모듈을 대신하는 임시 모듈"},{"term":"드라이버(Driver)","desc":"상향식 통합 테스트에서 상위 모듈을 대신하는 임시 모듈"},{"term":"테스트 데이터 생성 방법","desc":"자료 흐름도, 기능 테스트, 입력 도메인 분석, 랜덤 테스트"}],"memo":"스터브·드라이버는 통합 테스트용 ‘대역 배우’다. 데이터를 찾는 방법이 아니다."}},{"id":"written-2025-3-41","no":41,"unit":"데이터베이스 구축","q":"다음 중 정규화의 필요성과 거리가 먼 것은?","choices":["중복 데이터의 활성화","테이블 불일치 위험의 최소화","데이터 구조의 안정성 최대화","수정, 삭제 시 이상 현상의 최소화"],"ans":1,"exp":{"concept":"정규화는 테이블을 쪼개 중복 데이터를 줄이고, 삽입·삭제·갱신 때 생기는 이상 현상을 없애는 과정이다. 같은 정보가 여러 곳에 있으면 한 곳만 바뀌어 서로 맞지 않게 되기 때문이다.","choices":[{"verdict":"정답","why":"정규화는 중복 데이터를 활성화하는 것이 아니라 최소화하는 것이 목적이므로 필요성과 거리가 멀다."},{"verdict":"오답","why":"정규화는 테이블 간 데이터 불일치 위험을 최소화한다."},{"verdict":"오답","why":"정규화는 데이터 구조를 안정적으로 만든다."},{"verdict":"오답","why":"정규화는 삽입·수정·삭제 시 생기는 이상 현상을 최소화한다."}],"keywords":[{"term":"정규화(Normalization)","desc":"중복을 줄이고 이상 현상을 없애도록 릴레이션을 분해하는 과정"},{"term":"이상 현상(Anomaly)","desc":"삽입 이상, 삭제 이상, 갱신 이상"},{"term":"반정규화","desc":"성능을 위해 일부러 중복을 허용하는 기법"}],"memo":"정규화의 목적은 ‘중복 최소화’. 중복을 늘리는 표현이 있으면 그 보기가 답이다."}},{"id":"written-2025-3-42","no":42,"unit":"데이터베이스 구축","q":"다음 설명에 해당하는 트랜잭션의 특성은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>트랜잭션의 연산은 데이터베이스에 모두 반영되거나, 그렇지 않으면 전혀 반영되지 않아야 한다.</p></div>","choices":["Share","Atomicity","Consistency","Durability"],"ans":2,"exp":{"concept":"트랜잭션은 데이터베이스에서 한꺼번에 처리되어야 하는 작업 묶음이다. 원자성(Atomicity), 일관성(Consistency), 독립성(Isolation), 영속성(Durability) 네 가지 특성(ACID)을 가진다. 원자성은 모두 반영되거나 하나도 반영되지 않아야 한다는 성질이다. 계좌 이체에서 출금만 되고 입금이 안 되는 일이 없어야 하는 것과 같다.","choices":[{"verdict":"오답","why":"Share(공유)는 트랜잭션의 특성(ACID)에 해당하지 않는다."},{"verdict":"정답","why":"원자성(Atomicity)은 트랜잭션의 연산이 모두 반영되거나 전혀 반영되지 않아야 하는 성질이므로 정답이다."},{"verdict":"오답","why":"일관성(Consistency)은 트랜잭션 실행 후에도 데이터베이스가 일관된 상태를 유지해야 하는 성질이다."},{"verdict":"오답","why":"영속성(Durability)은 성공적으로 완료된 트랜잭션의 결과가 영구적으로 반영되어야 하는 성질이다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"All or Nothing, 모두 반영되거나 전혀 반영되지 않음"},{"term":"일관성(Consistency)","desc":"실행 후에도 일관된 상태 유지"},{"term":"독립성(Isolation)","desc":"실행 중인 트랜잭션에 다른 트랜잭션이 끼어들 수 없음"},{"term":"영속성(Durability)","desc":"완료된 결과는 영구히 반영"}],"memo":"ACID 중 ‘모두 아니면 전무(All or Nothing)’는 원자성이다."}},{"id":"written-2025-3-43","no":43,"unit":"데이터베이스 구축","q":"SQL 명령어를 사용 용도에 따라 DDL, DML, DCL로 구분할 때, 나머지 셋과 성격이 다른 것은?","choices":["INSERT","UPDATE","SELECT","GRANT"],"ans":4,"exp":{"concept":"SQL은 용도에 따라 나뉜다. DDL(데이터 정의어)은 CREATE, ALTER, DROP처럼 구조를 만들고, DML(데이터 조작어)은 SELECT, INSERT, UPDATE, DELETE처럼 데이터를 다루며, DCL(데이터 제어어)은 GRANT, REVOKE, COMMIT, ROLLBACK처럼 권한과 트랜잭션을 제어한다.","choices":[{"verdict":"오답","why":"INSERT는 데이터를 삽입하는 DML이다."},{"verdict":"오답","why":"UPDATE는 데이터를 수정하는 DML이다."},{"verdict":"오답","why":"SELECT는 데이터를 조회하는 DML이다."},{"verdict":"정답","why":"GRANT는 사용자에게 권한을 부여하는 DCL이므로 나머지 셋(DML)과 성격이 다르다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP, TRUNCATE"},{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"GRANT·REVOKE는 권한, 권한은 제어(Control)이므로 DCL이다."}},{"id":"written-2025-3-44","no":44,"unit":"데이터베이스 구축","q":"릴레이션 R1의 외래키가 NULL이 아닌 경우, 그 값은 참조 대상인 릴레이션 R2의 기본키 값과 일치해야 한다. 이러한 제약을 무엇이라 하는가?","choices":["널 제약성","고유 무결성","참조 무결성","정보 무결성"],"ans":3,"exp":{"concept":"참조 무결성은 외래키 값이 NULL이거나, 참조하는 릴레이션의 기본키 값 중 하나와 반드시 같아야 한다는 제약이다. 존재하지 않는 학과 번호를 가진 학생이 생기지 않게 막는 규칙이다.","choices":[{"verdict":"오답","why":"널 제약성은 출제 범위의 표준 무결성 이름이 아니다. 비슷한 널 무결성은 특정 속성 값이 NULL이 될 수 없다는 규칙으로, 외래키와 기본키의 일치와는 관계없다."},{"verdict":"오답","why":"고유 무결성은 특정 속성 값이 서로 달라야(중복 불가) 한다는 규칙이다."},{"verdict":"정답","why":"외래키 값은 NULL이거나 참조 릴레이션의 기본키 값과 같아야 한다는 제약이 참조 무결성이므로 정답이다."},{"verdict":"오답","why":"정보 무결성은 출제 범위의 표준 무결성 제약 이름이 아니다."}],"keywords":[{"term":"개체 무결성","desc":"기본키는 NULL이나 중복 값을 가질 수 없음"},{"term":"참조 무결성","desc":"외래키는 NULL이거나 참조 릴레이션의 기본키 값이어야 함"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인에 속해야 함"}],"memo":"‘외래키’가 나오면 참조 무결성, ‘기본키’ NULL 금지는 개체 무결성이다."}},{"id":"written-2025-3-45","no":45,"unit":"데이터베이스 구축","q":"관계 데이터 모델에서 릴레이션(Relation)에 들어 있는 튜플(Tuple)의 개수를 가리키는 용어는 무엇인가?","choices":["Cartesian product","Degree","Cardinality","Attribute"],"ans":3,"exp":{"concept":"릴레이션은 표로 생각하면 쉽다. 행 하나가 튜플(Tuple), 열 하나가 속성(Attribute)이다. 튜플의 개수를 카디널리티(Cardinality, 기수), 속성의 개수를 디그리(Degree, 차수)라 한다.","choices":[{"verdict":"오답","why":"카티션 프로덕트(Cartesian Product, 교차곱)는 두 릴레이션의 모든 튜플을 조합하는 관계대수 연산이다."},{"verdict":"오답","why":"디그리(Degree)는 속성(열)의 개수다."},{"verdict":"정답","why":"카디널리티(Cardinality)는 튜플(행)의 개수이므로 정답이다."},{"verdict":"오답","why":"애트리뷰트(Attribute)는 릴레이션의 열, 즉 속성 자체를 말한다."}],"keywords":[{"term":"튜플(Tuple)","desc":"릴레이션의 행"},{"term":"속성(Attribute)","desc":"릴레이션의 열"},{"term":"카디널리티(Cardinality)","desc":"튜플 수, 기수"},{"term":"디그리(Degree)","desc":"속성 수, 차수"}],"memo":"카디널리티는 ‘카운트(셀 수 있는 행의 수)’, 디그리는 ‘차수(열의 수)’로 기억한다."}},{"id":"written-2025-3-46","no":46,"unit":"데이터베이스 구축","q":"애트리뷰트가 취할 수 있는 원자값들의 집합을 뜻하는 것은?","choices":["다형성","엔티티","튜플","도메인"],"ans":4,"exp":{"concept":"도메인(Domain)은 하나의 속성이 가질 수 있는 원자값들의 집합이다. 예를 들어 ‘성별’ 속성의 도메인은 {남, 여}, ‘학년’ 속성의 도메인은 {1, 2, 3, 4}다.","choices":[{"verdict":"오답","why":"다형성(Polymorphism)은 같은 메시지에 객체마다 다르게 반응하는 객체지향 개념이다."},{"verdict":"오답","why":"엔티티(Entity, 개체)는 데이터베이스에 표현하려는 현실 세계의 대상이다."},{"verdict":"오답","why":"튜플(Tuple)은 릴레이션의 행 하나를 말한다."},{"verdict":"정답","why":"도메인(Domain)은 속성이 취할 수 있는 원자값들의 집합이므로 정답이다."}],"keywords":[{"term":"도메인(Domain)","desc":"속성이 가질 수 있는 원자값의 집합"},{"term":"원자값(Atomic Value)","desc":"더 이상 나눌 수 없는 값"},{"term":"엔티티(Entity)","desc":"데이터로 표현하려는 현실 세계의 대상"}],"memo":"도메인은 ‘들어갈 수 있는 값의 범위’. 속성 하나마다 도메인 하나가 있다."}},{"id":"written-2025-3-47","no":47,"unit":"데이터베이스 구축","q":"릴레이션의 모든 튜플에 대하여 유일성은 만족하지만 최소성은 만족하지 않는 키는?","choices":["슈퍼키","외래키","후보키","기본키"],"ans":1,"exp":{"concept":"키는 튜플을 구분하는 속성(들)이다. 유일성은 키 값으로 튜플을 하나로 구별할 수 있는 성질, 최소성은 꼭 필요한 속성만으로 이루어진 성질이다. 슈퍼키는 유일성만, 후보키는 유일성과 최소성을 모두 만족한다.","choices":[{"verdict":"정답","why":"슈퍼키(Super Key)는 유일성은 만족하지만 최소성은 만족하지 않을 수 있는 키이므로 정답이다."},{"verdict":"오답","why":"외래키(Foreign Key)는 다른 릴레이션의 기본키를 참조하는 속성으로, 유일성을 요구하지 않는다."},{"verdict":"오답","why":"후보키(Candidate Key)는 유일성과 최소성을 모두 만족한다."},{"verdict":"오답","why":"기본키(Primary Key)는 후보키 중에서 선택한 키로, 유일성과 최소성을 모두 만족한다."}],"keywords":[{"term":"슈퍼키","desc":"유일성 O, 최소성 X"},{"term":"후보키","desc":"유일성 O, 최소성 O"},{"term":"기본키","desc":"후보키 중 선택한 대표 키, NULL 불가"},{"term":"대체키","desc":"기본키로 선택되지 않은 나머지 후보키"}],"memo":"슈퍼키는 ‘유일성만’, 후보키는 ‘유일성 + 최소성’."}},{"id":"written-2025-3-48","no":48,"unit":"데이터베이스 구축","q":"DELETE 명령에 관한 설명 중 틀린 것은?","choices":["WHERE 조건절 없이 DELETE 명령을 수행하면 DROP TABLE 명령을 수행한 것과 동일한 효과를 얻을 수 있다.","기본 사용 형식은 “DELETE FROM 테이블 [WHERE 조건];” 이다.","SQL을 사용 용도에 따라 분류하면 DML에 해당한다.","테이블의 행을 삭제하는 데 사용한다."],"ans":1,"exp":{"concept":"DELETE는 테이블의 행(튜플)을 지우는 DML 명령이다. WHERE 없이 실행하면 모든 행이 지워지지만 테이블 구조는 그대로 남는다. DROP TABLE은 테이블 구조까지 통째로 없애는 DDL 명령이다.","choices":[{"verdict":"정답","why":"WHERE 없이 DELETE를 실행하면 모든 행만 삭제되고 테이블 구조는 남는다. 테이블 자체를 없애는 DROP TABLE과는 효과가 다르므로 틀린 설명이다."},{"verdict":"오답","why":"DELETE의 기본 형식은 DELETE FROM 테이블 [WHERE 조건];이다."},{"verdict":"오답","why":"DELETE는 데이터를 조작하는 DML에 해당한다."},{"verdict":"오답","why":"DELETE는 테이블의 행을 삭제하는 데 사용한다."}],"keywords":[{"term":"DELETE","desc":"행 삭제, DML, 테이블 구조는 남음"},{"term":"DROP TABLE","desc":"테이블 구조까지 삭제, DDL"},{"term":"TRUNCATE","desc":"테이블의 모든 행을 삭제하는 DDL, 구조는 남음"}],"memo":"DELETE는 내용물만, DROP은 그릇까지 버린다."}},{"id":"written-2025-3-49","no":49,"unit":"데이터베이스 구축","q":"다음 보기에 해당하는 함수 종속의 추론 규칙은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>X → Y이고 Y → Z이면 X → Z이다.</p></div>","choices":["분해 규칙","결합 규칙","반사 규칙","이행 규칙"],"ans":4,"exp":{"concept":"함수 종속의 추론 규칙(암스트롱 공리)은 이미 알려진 종속으로부터 새로운 종속을 끌어내는 규칙이다. X → Y이고 Y → Z이면 X → Z라는 규칙은 화살표가 이어져 건너뛰는 모양이라 이행 규칙이라 한다.","choices":[{"verdict":"오답","why":"분해 규칙은 X → YZ이면 X → Y이고 X → Z라는 규칙이다."},{"verdict":"오답","why":"결합 규칙(합집합 규칙)은 X → Y이고 X → Z이면 X → YZ라는 규칙이다."},{"verdict":"오답","why":"반사 규칙은 Y가 X의 부분집합이면 X → Y라는 규칙이다."},{"verdict":"정답","why":"X → Y이고 Y → Z이면 X → Z라는 규칙은 이행 규칙이므로 정답이다."}],"keywords":[{"term":"반사 규칙","desc":"Y ⊆ X이면 X → Y"},{"term":"첨가(증가) 규칙","desc":"X → Y이면 XZ → YZ"},{"term":"이행 규칙","desc":"X → Y, Y → Z이면 X → Z"},{"term":"결합·분해 규칙","desc":"X → Y, X → Z ⇔ X → YZ"}],"memo":"A가 B를, B가 C를 결정하면 A가 C를 결정한다. 징검다리를 건너는 ‘이행’이다."}},{"id":"written-2025-3-50","no":50,"unit":"데이터베이스 구축","q":"STUDENT 테이블에 독일어과 학생 50명, 중국어과 학생 30명, 영어영문학과 학생 50명의 정보가 저장되어 있다고 할 때, 다음 두 SQL문을 실행한 결과의 튜플 수는? (단, DEPT 컬럼은 학과명이다)<pre class=\"q-sql\"><code class=\"language-sql\">ⓐ SELECT DEPT FROM STUDENT;\nⓑ SELECT DISTINCT DEPT FROM STUDENT;</code></pre>","choices":["ⓐ 3, ⓑ 3","ⓐ 50, ⓑ 3","ⓐ 130, ⓑ 3","ⓐ 130, ⓑ 130"],"ans":3,"exp":{"concept":"SELECT는 조건이 없으면 모든 행을 결과로 돌려준다. DISTINCT를 붙이면 결과에서 같은 값을 하나만 남긴다. 학생은 50 + 30 + 50 = 130명이고, 학과는 독일어과, 중국어과, 영어영문학과 3종류다.","choices":[{"verdict":"오답","why":"ⓐ는 DISTINCT가 없어 학생 수만큼 행이 나오므로 3이 아니다."},{"verdict":"오답","why":"ⓐ는 전체 학생 130명 모두의 학과가 출력되므로 50이 아니다."},{"verdict":"정답","why":"ⓐ는 WHERE가 없어 130개 행 전부, ⓑ는 중복을 없애 학과 3종류만 남으므로 130, 3이 정답이다."},{"verdict":"오답","why":"ⓑ는 DISTINCT로 중복 학과명을 제거하므로 130이 아니라 3이다."}],"keywords":[{"term":"DISTINCT","desc":"SELECT 결과에서 중복 행을 제거"},{"term":"ALL","desc":"중복을 포함한 모든 행 출력, SELECT의 기본값"}],"memo":"DISTINCT가 있으면 ‘종류 수’, 없으면 ‘전체 행 수’."}},{"id":"written-2025-3-51","no":51,"unit":"데이터베이스 구축","q":"개체-관계 모델(E-R)의 그래픽 표현으로 옳지 않은 것은 어느 것인가?","choices":["연결 - 삼각형","속성 - 원형","개체 타입 - 사각형","관계 타입 - 마름모"],"ans":1,"exp":{"concept":"E-R 모델(개체-관계 모델)은 현실 세계를 개체, 속성, 관계로 그림으로 표현한다. 개체 타입은 사각형, 속성은 타원(원형), 관계 타입은 마름모, 이들을 잇는 연결은 선으로 그린다.","choices":[{"verdict":"정답","why":"개체 타입과 관계 타입, 속성을 연결하는 것은 삼각형이 아니라 선(링크)으로 표시하므로 옳지 않다."},{"verdict":"오답","why":"속성(Attribute)은 타원(원형)으로 표시한다."},{"verdict":"오답","why":"개체 타입(Entity Type)은 사각형으로 표시한다."},{"verdict":"오답","why":"관계 타입(Relationship Type)은 마름모로 표시한다."}],"keywords":[{"term":"사각형","desc":"개체 타입"},{"term":"마름모","desc":"관계 타입"},{"term":"타원","desc":"속성(밑줄 친 타원은 기본키 속성)"},{"term":"선(링크)","desc":"개체 타입과 속성, 관계를 연결"}],"memo":"E-R 기호는 사각형·마름모·타원·선. DFD와 마찬가지로 삼각형은 없다."}},{"id":"written-2025-3-52","no":52,"unit":"데이터베이스 구축","q":"관계해석에서 ‘모든 것에 대하여’라는 의미를 나타내는 논리 기호는 무엇인가?","choices":["∃","∈","⊂","∀"],"ans":4,"exp":{"concept":"관계해석은 원하는 데이터가 ‘무엇인지’를 술어 논리 식으로 표현하는 비절차적 언어다. 이때 정량자(Quantifier)를 쓰는데, ∀는 ‘모든 것에 대하여(For All)’, ∃는 ‘어떤 것이 존재한다(There Exists)’는 뜻이다.","choices":[{"verdict":"오답","why":"∃는 ‘존재한다(There Exists)’는 뜻의 존재 정량자다."},{"verdict":"오답","why":"∈는 ‘원소이다(속한다)’는 뜻의 집합 기호다."},{"verdict":"오답","why":"⊂는 ‘부분집합이다’는 뜻의 집합 기호다."},{"verdict":"정답","why":"∀는 ‘모든 것에 대하여(For All)’라는 뜻의 전칭 정량자이므로 정답이다."}],"keywords":[{"term":"∀ (전칭 정량자)","desc":"모든 것에 대하여, For All"},{"term":"∃ (존재 정량자)","desc":"어떤 것이 존재한다, There Exists"},{"term":"관계해석","desc":"원하는 정보를 술어 논리로 정의하는 비절차적 언어"}],"memo":"∀는 All의 A를 뒤집은 모양, ∃는 Exists의 E를 뒤집은 모양이다."}},{"id":"written-2025-3-53","no":53,"unit":"데이터베이스 구축","q":"데이터베이스 설계에서 물리적 설계 단계에서 수행하는 사항으로 볼 수 없는 것은?","choices":["목표 DBMS에 맞는 스키마 설계","레코드 집중의 분석 및 설계","저장 레코드 양식 설계","접근 경로 설계"],"ans":1,"exp":{"concept":"데이터베이스 설계는 요구 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행된다. 논리적 설계는 목표 DBMS의 데이터 모델에 맞게 스키마를 만드는 단계이고, 물리적 설계는 그 스키마를 실제 저장 장치에 어떻게 저장할지(레코드 양식, 레코드 집중, 접근 경로) 정하는 단계다.","choices":[{"verdict":"정답","why":"목표 DBMS에 맞는 스키마 설계는 논리적 설계 단계에서 수행하므로 물리적 설계와 거리가 멀다."},{"verdict":"오답","why":"레코드 집중(Record Clustering)의 분석 및 설계는 물리적 설계에서 수행한다."},{"verdict":"오답","why":"저장 레코드 양식 설계는 물리적 설계에서 수행한다."},{"verdict":"오답","why":"인덱스 등 접근 경로 설계는 물리적 설계에서 수행한다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, DBMS에 독립적인 개념 스키마"},{"term":"논리적 설계","desc":"목표 DBMS에 맞는 논리 스키마 설계, 정규화"},{"term":"물리적 설계","desc":"저장 레코드 양식, 레코드 집중, 접근 경로 설계"}],"memo":"‘저장·레코드·접근 경로’처럼 디스크에 가까운 단어는 물리적 설계, ‘스키마·DBMS 데이터 모델’은 논리적 설계다."}},{"id":"written-2025-3-54","no":54,"unit":"데이터베이스 구축","q":"로킹 단위(Locking Granularity)에 관한 설명 중 옳은 것은?","choices":["로킹 단위가 커지면 병행성 수준은 낮아진다.","로킹은 파일 단위로만 이루어지므로 레코드와 필드는 로킹 단위가 될 수 없다.","로킹 단위가 커지면 병행 제어 기법은 복잡해진다.","로킹 단위가 작아지면 로크(lock)의 수는 적어진다."],"ans":1,"exp":{"concept":"로킹(Locking)은 트랜잭션이 데이터를 쓰는 동안 다른 트랜잭션이 못 쓰게 잠그는 병행 제어 기법이다. 로킹 단위는 데이터베이스, 파일, 레코드, 필드 등이 될 수 있다. 단위가 크면 잠금 수가 적어 관리가 쉽지만 함께 쓸 수 있는 범위가 줄어 병행성이 떨어지고, 단위가 작으면 반대가 된다.","choices":[{"verdict":"정답","why":"로킹 단위가 커지면 한 번에 잠기는 범위가 넓어져 동시에 처리할 수 있는 트랜잭션이 줄어들므로 병행성 수준이 낮아진다. 옳은 설명이다."},{"verdict":"오답","why":"로킹 단위는 데이터베이스, 파일, 레코드, 필드 등 다양하게 정할 수 있으므로 틀린 설명이다."},{"verdict":"오답","why":"로킹 단위가 커지면 관리할 로크 수가 줄어 병행 제어 기법은 오히려 간단해진다."},{"verdict":"오답","why":"로킹 단위가 작아지면 잠가야 할 대상이 많아져 로크의 수는 많아진다."}],"keywords":[{"term":"로킹(Locking)","desc":"데이터에 잠금을 걸어 동시 접근을 제어하는 병행 제어 기법"},{"term":"로킹 단위 큼","desc":"로크 수 적음, 제어 간단, 병행성 낮음"},{"term":"로킹 단위 작음","desc":"로크 수 많음, 제어 복잡, 병행성 높음"}],"memo":"건물 전체를 잠그면(큰 단위) 관리는 쉽지만 아무도 못 들어간다. 방마다 잠그면(작은 단위) 열쇠는 많지만 여러 사람이 동시에 쓴다."}},{"id":"written-2025-3-55","no":55,"unit":"데이터베이스 구축","q":"DDL(Data Define Language)의 명령어 가운데 스키마, 도메인, 인덱스 등을 정의하는 데 사용되는 SQL문은?","choices":["INSERT","ALTER","CREATE","SELECT"],"ans":3,"exp":{"concept":"DDL(Data Definition Language, 데이터 정의어)은 데이터베이스의 구조를 정의하는 명령으로 CREATE, ALTER, DROP 등이 있다. 그중 CREATE는 스키마, 도메인, 테이블, 뷰, 인덱스 같은 객체를 새로 정의(생성)한다.","choices":[{"verdict":"오답","why":"INSERT는 테이블에 새 행을 삽입하는 DML이다."},{"verdict":"오답","why":"ALTER는 이미 만들어진 테이블의 구조를 변경하는 DDL로, 새로 정의하는 명령은 아니다."},{"verdict":"정답","why":"CREATE는 스키마, 도메인, 테이블, 뷰, 인덱스를 정의하는 DDL이므로 정답이다."},{"verdict":"오답","why":"SELECT는 데이터를 조회하는 DML이다."}],"keywords":[{"term":"CREATE","desc":"스키마, 도메인, 테이블, 뷰, 인덱스 정의"},{"term":"ALTER","desc":"테이블 구조 변경"},{"term":"DROP","desc":"스키마, 도메인, 테이블, 뷰, 인덱스 삭제"}],"memo":"새로 ‘만든다(정의한다)’는 CREATE, ‘바꾼다’는 ALTER, ‘없앤다’는 DROP."}},{"id":"written-2025-3-56","no":56,"unit":"데이터베이스 구축","q":"다음 테이블 R과 S에 대해 아래 SQL문을 실행했을 때, 그 실행 결과로 옳은 것은?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><div class=\"q-tbl-title\">R</div><table class=\"q-tbl is-data\"><thead><tr><th>A</th><th>B</th></tr></thead><tbody><tr><td>1</td><td>A</td></tr><tr><td>3</td><td>B</td></tr></tbody></table><div class=\"q-tbl-title\">S</div><table class=\"q-tbl is-data\"><thead><tr><th>A</th><th>B</th></tr></thead><tbody><tr><td>1</td><td>A</td></tr><tr><td>2</td><td>B</td></tr></tbody></table><pre class=\"q-sql\"><code class=\"language-sql\">SELECT A FROM R\nUNION ALL\nSELECT A FROM S;</code></pre></div>","choices":["<table class=\"q-tbl is-data is-center\"><tbody><tr><td>1</td></tr></tbody></table>","<table class=\"q-tbl is-data is-center\"><tbody><tr><td>3</td></tr><tr><td>2</td></tr></tbody></table>","<table class=\"q-tbl is-data is-center\"><tbody><tr><td>1</td></tr><tr><td>3</td></tr><tr><td>1</td></tr><tr><td>2</td></tr></tbody></table>","<table class=\"q-tbl is-data is-center\"><tbody><tr><td>1</td></tr><tr><td>3</td></tr></tbody></table>"],"ans":3,"exp":{"concept":"UNION ALL은 두 SELECT 결과를 위아래로 그대로 이어 붙이며 중복을 제거하지 않는다. UNION은 중복을 제거한다. R의 A 열은 1, 3이고 S의 A 열은 1, 2이므로, 이어 붙이면 1, 3, 1, 2의 네 행이 된다.","choices":[{"verdict":"오답","why":"1 하나만 나오는 것은 두 결과의 공통값만 구하는 INTERSECT의 결과다."},{"verdict":"오답","why":"3, 2는 어떤 집합 연산의 결과와도 맞지 않는다. 참고로 R에만 있는 값을 구하는 EXCEPT(차집합)의 결과는 3이다."},{"verdict":"정답","why":"UNION ALL은 중복을 제거하지 않고 R의 1, 3 뒤에 S의 1, 2를 이어 붙이므로 1, 3, 1, 2가 정답이다."},{"verdict":"오답","why":"1, 3은 R만 조회한 결과다. UNION으로 중복을 없애더라도 1, 3, 2 세 행이 나온다."}],"keywords":[{"term":"UNION","desc":"합집합, 중복 제거"},{"term":"UNION ALL","desc":"합집합, 중복 포함"},{"term":"INTERSECT","desc":"교집합"},{"term":"EXCEPT(MINUS)","desc":"차집합"}],"memo":"ALL이 붙으면 ‘전부 다’, 즉 중복도 지우지 않는다. 결과 행 수 = 두 결과 행 수의 합."}},{"id":"written-2025-3-57","no":57,"unit":"데이터베이스 구축","q":"다음 중 관계대수의 순수 관계 연산자에 해당하지 않는 것은?","choices":["Select","Project","Division","Cartesian Product"],"ans":4,"exp":{"concept":"관계대수 연산자는 순수 관계 연산자와 일반 집합 연산자로 나뉜다. 순수 관계 연산자는 릴레이션 구조를 위해 따로 만든 Select, Project, Join, Division이다. 합집합, 교집합, 차집합, 교차곱(Cartesian Product)은 수학의 집합 연산을 가져온 일반 집합 연산자다.","choices":[{"verdict":"오답","why":"Select(σ)는 조건을 만족하는 튜플(행)을 고르는 순수 관계 연산자다."},{"verdict":"오답","why":"Project(π)는 원하는 속성(열)만 뽑는 순수 관계 연산자다."},{"verdict":"오답","why":"Division(÷)은 한 릴레이션이 다른 릴레이션의 모든 값과 관련된 튜플을 구하는 순수 관계 연산자다."},{"verdict":"정답","why":"Cartesian Product(×, 교차곱)는 두 릴레이션의 모든 튜플을 조합하는 일반 집합 연산자이므로 순수 관계 연산자가 아니다."}],"keywords":[{"term":"순수 관계 연산자","desc":"Select(σ), Project(π), Join(⋈), Division(÷)"},{"term":"일반 집합 연산자","desc":"합집합(∪), 교집합(∩), 차집합(−), 교차곱(×)"},{"term":"교차곱","desc":"두 릴레이션 튜플의 모든 조합, 차수는 더하고 카디널리티는 곱함"}],"memo":"순수 관계 연산자는 ‘셀프로조디’(Select, Project, Join, Division)."}},{"id":"written-2025-3-58","no":58,"unit":"데이터베이스 구축","q":"정규화를 수행하지 않아 발생하는 이상(anomaly) 현상의 종류에 관한 설명 중 옳지 않은 것은?","choices":["삽입 이상이란 릴레이션에 데이터를 삽입할 때 의도와 상관없이 원하지 않는 값들까지 함께 삽입되는 현상이다.","종속 이상이란 하나의 릴레이션에 하나 이상의 함수적 종속성이 존재하는 현상을 말한다.","갱신 이상이란 릴레이션의 튜플에 있는 속성값을 갱신할 때 일부 튜플의 정보만 갱신되어 정보에 모순이 발생하는 현상이다.","삭제 이상이란 릴레이션에서 한 튜플을 삭제할 때 의도와 상관없는 값들이 함께 삭제되는 연쇄 삭제 현상이다."],"ans":2,"exp":{"concept":"정규화하지 않은 릴레이션에서는 이상(Anomaly) 현상이 생긴다. 이상 현상은 삽입 이상, 삭제 이상, 갱신 이상 세 가지다. 함수적 종속이 있다는 것 자체는 이상 현상이 아니며, ‘종속 이상’이라는 종류는 없다.","choices":[{"verdict":"오답","why":"삽입 이상은 데이터를 삽입할 때 원하지 않는 값까지 함께 넣어야 하거나 삽입이 안 되는 현상이다."},{"verdict":"정답","why":"이상 현상은 삽입·삭제·갱신 세 가지뿐이며 종속 이상은 없다. 하나의 릴레이션에 함수적 종속성이 있는 것은 정상적인 성질이므로 틀린 설명이다."},{"verdict":"오답","why":"갱신 이상은 일부 튜플만 갱신되어 정보에 모순이 생기는 현상이다."},{"verdict":"오답","why":"삭제 이상은 한 튜플을 삭제할 때 의도하지 않은 값들까지 함께 삭제되는 연쇄 삭제 현상이다."}],"keywords":[{"term":"삽입 이상","desc":"원하지 않는 값까지 함께 삽입해야 하는 현상"},{"term":"삭제 이상","desc":"원하지 않는 값까지 함께 삭제되는 현상"},{"term":"갱신 이상","desc":"일부만 갱신되어 데이터가 서로 모순되는 현상"}],"memo":"이상 현상은 ‘삽삭갱’ 세 가지뿐이다."}},{"id":"written-2025-3-59","no":59,"unit":"데이터베이스 구축","q":"다음 중 뷰(View)의 장점에 해당하지 않는 것은?","choices":["논리적 독립성을 제공함","뷰 자체로 인덱스를 가짐","데이터 보안이 용이함","사용자의 데이터 관리가 용이함"],"ans":2,"exp":{"concept":"뷰(View)는 기본 테이블에서 유도된 가상 테이블이다. 실제 데이터를 따로 저장하지 않으므로 자체 인덱스를 가질 수 없다. 장점은 논리적 독립성 제공, 데이터 보안, 데이터 관리 간소화 등이고, 단점은 독자적인 인덱스 불가, 정의 변경 불가, 삽입·삭제·갱신 제약이다.","choices":[{"verdict":"오답","why":"뷰는 기본 테이블 구조가 바뀌어도 사용자에게 같은 모습을 보여 줄 수 있어 논리적 독립성을 제공한다."},{"verdict":"정답","why":"뷰는 물리적으로 저장되지 않는 가상 테이블이라 독자적인 인덱스를 가질 수 없다. 장점이 아니라 단점이다."},{"verdict":"오답","why":"뷰를 통해 필요한 열과 행만 보여 주면 나머지 데이터를 감출 수 있어 보안이 쉽다."},{"verdict":"오답","why":"복잡한 질의를 뷰로 만들어 두면 사용자가 데이터를 간단하게 다룰 수 있다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 독립성, 보안, 데이터 관리 용이"},{"term":"뷰의 단점","desc":"독자적 인덱스 불가, 정의 변경 불가(삭제 후 재생성), 갱신 제약"}],"memo":"뷰는 ‘창문’이다. 창문 자체에는 물건(데이터)도 색인(인덱스)도 없다."}},{"id":"written-2025-3-60","no":60,"unit":"데이터베이스 구축","q":"데이터베이스 시스템에서 삽입, 갱신, 삭제 등의 이벤트가 발생할 때마다 관련 작업이 자동으로 수행되도록 하는 절차형 SQL은 무엇인가?","choices":["트리거(Trigger)","복귀(Rollback)","무결성(Integrity)","잠금(Lock)"],"ans":1,"exp":{"concept":"트리거(Trigger)는 테이블에 삽입, 갱신, 삭제 같은 이벤트가 일어날 때 자동으로 실행되는 절차형 SQL이다. 방아쇠를 당기면 총알이 나가듯, 이벤트가 발생하면 정해 둔 작업이 저절로 수행된다.","choices":[{"verdict":"정답","why":"트리거(Trigger)는 이벤트 발생 시 관련 작업이 자동으로 수행되는 절차형 SQL이므로 정답이다."},{"verdict":"오답","why":"롤백(Rollback)은 트랜잭션이 비정상 종료되었을 때 작업을 취소하고 이전 상태로 되돌리는 명령이다."},{"verdict":"오답","why":"무결성(Integrity)은 데이터의 정확성과 일관성을 유지하는 성질이다."},{"verdict":"오답","why":"잠금(Lock)은 동시 접근을 막기 위해 데이터에 거는 병행 제어 장치다."}],"keywords":[{"term":"트리거(Trigger)","desc":"이벤트 발생 시 자동 실행되는 절차형 SQL"},{"term":"프로시저(Procedure)","desc":"호출해서 실행하는 일련의 SQL 작업 묶음"},{"term":"사용자 정의 함수","desc":"처리 결과를 단일 값으로 반환하는 절차형 SQL"}],"memo":"‘자동으로 수행’ = 트리거, ‘호출해서 실행’ = 프로시저."}},{"id":"written-2025-3-61","no":61,"unit":"프로그래밍 언어 활용","q":"다음은 파이썬으로 작성된 반복문 코드이다. 이 코드를 실행한 결과는?<pre class=\"qcode\"><code class=\"language-python\">while(True) :\n    print('A')\n    print('B')\n    break\n    print('C')\nprint('D')</code></pre>","choices":["A, B, C 까지만 출력이 이루어진다.","A, B, D 까지만 출력이 이루어진다.","A, B, C 출력이 반복해서 이루어진다.","A, B 출력이 반복해서 이루어진다."],"ans":2,"exp":{"concept":"while(True)는 조건이 항상 참이라 끝없이 반복하려는 반복문이다. 하지만 반복문 안에서 break를 만나면 그 즉시 반복문을 빠져나간다. break 뒤에 있는 문장은 실행되지 않는다.","choices":[{"verdict":"오답","why":"break가 print('C')보다 먼저 실행되므로 C는 출력되지 않는다."},{"verdict":"정답","why":"A, B를 출력한 뒤 break로 반복문을 빠져나가고, 반복문 바깥의 print('D')가 실행되므로 A, B, D가 출력된다."},{"verdict":"오답","why":"C는 break 뒤에 있어 한 번도 실행되지 않고, 반복도 첫 회에서 끝난다."},{"verdict":"오답","why":"break 때문에 첫 번째 반복에서 바로 빠져나가므로 A, B가 반복 출력되지 않는다."}],"keywords":[{"term":"break","desc":"가장 가까운 반복문을 즉시 빠져나감"},{"term":"continue","desc":"남은 문장을 건너뛰고 다음 반복으로 넘어감"},{"term":"while True","desc":"조건이 항상 참인 무한 반복, break로 빠져나옴"}],"memo":"break 아래 줄은 죽은 코드다. 반복문 밖의 문장은 break 뒤에 실행된다."}},{"id":"written-2025-3-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 중 페이지 교체(Page Replacement) 알고리즘에 해당하지 않는 것은?","choices":["NUR","SCF","LRU","OPT"],"ans":2,"exp":{"concept":"페이지 교체 알고리즘은 메모리가 가득 찼을 때 어떤 페이지를 내보낼지 정하는 방법이다. OPT, FIFO, LRU, LFU, NUR, SCR(2차 기회) 등이 있다.","choices":[{"verdict":"오답","why":"NUR(Not Used Recently)은 최근에 사용되지 않은 페이지를 참조 비트와 변형 비트로 골라 교체하는 페이지 교체 알고리즘이다."},{"verdict":"정답","why":"SCF는 페이지 교체 알고리즘 이름이 아니다. 비슷한 이름의 2차 기회 교체는 SCR(Second Chance Replacement)이다."},{"verdict":"오답","why":"LRU(Least Recently Used)는 가장 오랫동안 사용되지 않은 페이지를 교체하는 알고리즘이다."},{"verdict":"오답","why":"OPT(Optimal)는 앞으로 가장 오랫동안 사용되지 않을 페이지를 교체하는 최적 알고리즘이다."}],"keywords":[{"term":"OPT","desc":"앞으로 가장 오래 쓰지 않을 페이지 교체, 이론상 최적"},{"term":"FIFO","desc":"가장 먼저 들어온 페이지 교체"},{"term":"LRU","desc":"가장 오랫동안 사용하지 않은 페이지 교체"},{"term":"LFU / NUR / SCR","desc":"사용 횟수 최소 / 최근 미사용 / FIFO에 참조 비트로 2차 기회 부여"}],"memo":"2차 기회는 SCR(Second Chance Replacement). SCF처럼 철자를 바꾼 보기를 조심한다."}},{"id":"written-2025-3-63","no":63,"unit":"프로그래밍 언어 활용","q":"리눅스 Bash 쉘(Shell)의 export에 대한 설명으로 옳지 않은 것은?","choices":["사용자가 생성한 변수는 export 명령어로 표시하지 않는 한 현재 쉘에만 국한된다.","변수를 출력하려면 export를 사용해야 한다.","export를 매개변수 없이 사용하면 현재 설정된 환경변수들이 출력된다.","export된 변수는 이후 실행하는 자식 프로세스의 환경으로 전달된다."],"ans":2,"exp":{"concept":"리눅스 Bash에서 그냥 만든 변수는 현재 쉘에서만 쓰인다. export로 지정하면 환경변수가 되어 이후 실행하는 자식 프로세스에도 전달된다. 변수 값을 화면에 출력하는 것은 echo 같은 명령으로 하며 export가 필요하지 않다.","choices":[{"verdict":"오답","why":"export하지 않은 변수는 현재 쉘에서만 쓰이는 지역(쉘) 변수다."},{"verdict":"정답","why":"변수를 출력할 때는 echo $변수명처럼 하면 되며 export가 필요하지 않다. export는 변수를 자식 프로세스에 전달하는 명령이므로 틀린 설명이다."},{"verdict":"오답","why":"export를 매개변수 없이 실행하면 현재 export된 환경변수 목록이 출력된다."},{"verdict":"오답","why":"export된 변수는 이후 실행하는 자식 프로세스의 환경으로 전달된다."}],"keywords":[{"term":"export","desc":"변수를 환경변수로 만들어 자식 프로세스에 전달"},{"term":"echo","desc":"문자열이나 변수 값을 화면에 출력"},{"term":"env","desc":"현재 환경변수 목록 출력"}],"memo":"export는 ‘수출’, 즉 자식 프로세스로 내보내는 명령이다. 출력은 echo."}},{"id":"written-2025-3-64","no":64,"unit":"프로그래밍 언어 활용","q":"TCP/IP 프로토콜에서 TCP는 어느 계층에 해당하는가?","choices":["트랜스포트 계층","데이터 링크 계층","세션 계층","네트워크 계층"],"ans":1,"exp":{"concept":"TCP/IP 모델은 네트워크 액세스, 인터넷, 전송(트랜스포트), 응용의 4계층이다. TCP(Transmission Control Protocol)는 연결을 맺고 데이터를 순서대로 신뢰성 있게 전달하는 전송 계층 프로토콜이다.","choices":[{"verdict":"정답","why":"TCP는 UDP와 함께 전송(트랜스포트) 계층 프로토콜이므로 정답이다."},{"verdict":"오답","why":"데이터 링크 계층에는 이더넷, HDLC 등이 있다."},{"verdict":"오답","why":"세션 계층은 OSI 7계층의 5계층으로, TCP의 계층이 아니다. TCP/IP 4계층 모델에는 세션 계층이 따로 없다."},{"verdict":"오답","why":"네트워크 계층(인터넷 계층)에는 IP, ICMP, ARP 등이 있다."}],"keywords":[{"term":"전송 계층","desc":"TCP, UDP"},{"term":"인터넷(네트워크) 계층","desc":"IP, ICMP, IGMP, ARP"},{"term":"TCP","desc":"연결형, 신뢰성 있는 순서 보장 전송"},{"term":"UDP","desc":"비연결형, 빠르지만 신뢰성 보장 없음"}],"memo":"TCP와 UDP는 함께 전송 계층, IP는 그 아래 네트워크 계층."}},{"id":"written-2025-3-65","no":65,"unit":"프로그래밍 언어 활용","q":"배치 프로그램의 자동 수행 주기 가운데, 사용자가 미리 특정 조건을 설정해 두고 그 조건이 충족되는 경우에만 수행되도록 하는 것은?","choices":["이벤트성 배치","정기 배치","사용자 배치","On-Demand 배치"],"ans":1,"exp":{"concept":"배치 프로그램은 사용자 개입 없이 정해진 작업을 한꺼번에 자동 처리하는 프로그램이다. 수행 주기에 따라 정기 배치, 이벤트성 배치, On-Demand 배치로 나뉜다.","choices":[{"verdict":"정답","why":"이벤트성 배치는 미리 정해 둔 조건이 충족될 때만 자동으로 실행되므로 정답이다."},{"verdict":"오답","why":"정기 배치는 매일, 매주, 매월처럼 정해진 시점에 실행된다."},{"verdict":"오답","why":"사용자 배치는 배치 프로그램의 수행 주기 분류에 해당하지 않는다."},{"verdict":"오답","why":"On-Demand 배치는 사용자가 명시적으로 요청할 때 실행된다."}],"keywords":[{"term":"정기 배치","desc":"정해진 기간(일·주·월)에 실행"},{"term":"이벤트성 배치","desc":"특정 조건이 충족될 때 실행"},{"term":"On-Demand 배치","desc":"사용자 요청 시 실행"}],"memo":"‘조건이 충족되면’ = 이벤트, ‘요청하면’ = On-Demand, ‘정해진 날’ = 정기."}},{"id":"written-2025-3-66","no":66,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 가운데 프로토콜 데이터 단위(PDU)가 메시지(Message)에 해당하지 않는 것은?","choices":["표현 계층","전송 계층","응용 계층","세션 계층"],"ans":2,"exp":{"concept":"프로토콜 데이터 단위(PDU)는 각 계층에서 주고받는 데이터 묶음의 이름이다. OSI 7계층에서 응용·표현·세션 계층은 메시지(데이터), 전송 계층은 세그먼트, 네트워크 계층은 패킷, 데이터 링크 계층은 프레임, 물리 계층은 비트다.","choices":[{"verdict":"오답","why":"표현 계층의 PDU는 메시지(데이터)다."},{"verdict":"정답","why":"전송 계층의 PDU는 메시지가 아니라 세그먼트(Segment)이므로 정답이다."},{"verdict":"오답","why":"응용 계층의 PDU는 메시지(데이터)다."},{"verdict":"오답","why":"세션 계층의 PDU는 메시지(데이터)다."}],"keywords":[{"term":"메시지(데이터)","desc":"응용·표현·세션 계층"},{"term":"세그먼트","desc":"전송 계층"},{"term":"패킷","desc":"네트워크 계층"},{"term":"프레임 / 비트","desc":"데이터 링크 계층 / 물리 계층"}],"memo":"아래에서부터 ‘비프패세메’(비트, 프레임, 패킷, 세그먼트, 메시지)."}},{"id":"written-2025-3-67","no":67,"unit":"프로그래밍 언어 활용","q":"아래의 페이지 참조 열(Page reference)에 대해 페이지 교체 기법으로 선입선출 알고리즘을 적용할 때 페이지 부재(Page Fault)는 몇 회 발생하는가? (단 , 할당된 페이지 프레임 수는 3이며, 처음에는 모든 프레임이 비어 있다.)<div class=\"q-spec\"><div class=\"q-spec__label\">&lt;페이지 참조열&gt;</div><p>7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2, 1, 2, 0, 1, 7, 0</p></div>","choices":["13","14","15","20"],"ans":2,"exp":{"concept":"선입선출(FIFO) 교체는 메모리에 가장 먼저 들어온 페이지부터 내보낸다. 찾는 페이지가 프레임에 없으면 페이지 부재가 한 번 일어나고, 프레임이 가득 찼다면 가장 오래 머문 페이지를 내보낸다. 참조열을 하나씩 따라가며 프레임 상태를 적으면 된다.","choices":[{"verdict":"오답","why":"13회가 아니다. 프레임 3개로 19개 참조를 처리하면 부재가 14회 일어난다."},{"verdict":"정답","why":"7, 0, 1(부재 3회, [7,0,1]) → 2 부재 [0,1,2] → 0 적중 → 3 부재 [1,2,3] → 0 부재 [2,3,0] → 4 부재 [3,0,4] → 2 부재 [0,4,2] → 3 부재 [4,2,3] → 0 부재 [2,3,0] → 3, 2 적중 → 1 부재 [3,0,1] → 2 부재 [0,1,2] → 0, 1 적중 → 7 부재 [1,2,7] → 0 부재 [2,7,0]. 부재는 모두 14회다."},{"verdict":"오답","why":"15회는 실제보다 1회 많다. 참조 19번 가운데 0, 3, 2, 0, 1 다섯 번은 이미 프레임에 있는 페이지라 적중하므로, 부재는 19 − 5 = 14회다."},{"verdict":"오답","why":"참조는 모두 19번이므로 부재가 20회일 수 없다. 이 중 적중 5번을 빼면 14회다."}],"keywords":[{"term":"FIFO 페이지 교체","desc":"가장 먼저 들어온 페이지를 교체"},{"term":"페이지 부재(Page Fault)","desc":"참조할 페이지가 주기억장치에 없는 상태"},{"term":"벨레이디의 모순(Belady's Anomaly)","desc":"FIFO에서 프레임 수를 늘려도 부재가 오히려 늘 수 있는 현상"}],"memo":"참조열 개수 − 적중 횟수 = 부재 횟수. 19 − 5 = 14로 검산한다."}},{"id":"written-2025-3-68","no":68,"unit":"프로그래밍 언어 활용","q":"다음은 정수 배열 a에 0에서 9까지의 무작위 수를 저장하는 Java 코드이다. 괄호 안에 들어갈 알맞은 코드는?<pre class=\"qcode\"><code class=\"language-java\">import (     ).*;\npublic class Test {\n    public static void main(String[] args) {\n        Random rand = new Random( );\n        int a[] = new int[6];\n        for(int i = 0; i &lt; 6; i++)\n            a[i] = rand.nextInt(10);\n    }\n}</code></pre>","choices":["java.io","java.lang","java.util","java.net"],"ans":3,"exp":{"concept":"Java에서 다른 패키지에 있는 클래스를 쓰려면 import로 불러와야 한다. 난수를 만드는 Random 클래스는 java.util 패키지에 있다. rand.nextInt(10)은 0 이상 10 미만, 즉 0~9의 정수를 돌려준다.","choices":[{"verdict":"오답","why":"java.io는 파일과 스트림 입출력 클래스가 있는 패키지로, Random 클래스가 없어 컴파일 오류가 난다."},{"verdict":"오답","why":"java.lang은 String, Math, System 등 기본 클래스가 있는 패키지로, import하지 않아도 자동으로 포함되지만 Random은 들어 있지 않다."},{"verdict":"정답","why":"Random 클래스는 java.util 패키지에 있으므로 import java.util.*;가 들어가야 한다."},{"verdict":"오답","why":"java.net은 소켓, URL 등 네트워크 클래스가 있는 패키지로, Random 클래스가 없다."}],"keywords":[{"term":"java.util","desc":"Random, Scanner, ArrayList, HashMap 등 유틸리티 클래스"},{"term":"java.lang","desc":"String, Math, System 등, 자동 import"},{"term":"java.io","desc":"파일·스트림 입출력"},{"term":"nextInt(n)","desc":"0 이상 n 미만의 정수 난수 반환"}],"memo":"Random과 Scanner는 java.util. Math.random()은 java.lang이라 import가 필요 없다."}},{"id":"written-2025-3-69","no":69,"unit":"프로그래밍 언어 활용","q":"오류 제어에 쓰이는 자동 반복 요청 방식(ARQ)에 해당하지 않는 것은?","choices":["Stop-and-wait ARQ","Selective-Repeat ARQ","Go-back-N ARQ","Non-Acknowledge ARQ"],"ans":4,"exp":{"concept":"ARQ(Automatic Repeat reQuest, 자동 반복 요청)는 오류가 난 프레임을 수신 측이 알리면 송신 측이 다시 보내는 오류 제어 방식이다. 종류는 정지-대기(Stop-and-Wait) ARQ, Go-Back-N ARQ, 선택적 재전송(Selective-Repeat) ARQ, 적응적(Adaptive) ARQ다.","choices":[{"verdict":"오답","why":"Stop-and-Wait ARQ는 한 블록을 보낸 뒤 수신 측의 응답(ACK/NAK)을 기다리는 방식이다."},{"verdict":"오답","why":"Selective-Repeat ARQ는 오류가 난 블록만 골라 다시 보내는 방식이다."},{"verdict":"오답","why":"Go-Back-N ARQ는 오류가 난 블록부터 그 뒤의 모든 블록을 다시 보내는 방식이다."},{"verdict":"정답","why":"Non-Acknowledge ARQ는 ARQ의 종류가 아니다. NAK(부정 응답)는 ARQ에서 쓰이는 응답 신호의 이름일 뿐이다."}],"keywords":[{"term":"Stop-and-Wait ARQ","desc":"한 블록씩 보내고 응답을 기다림"},{"term":"Go-Back-N ARQ","desc":"오류 블록부터 이후 블록 모두 재전송"},{"term":"Selective-Repeat ARQ","desc":"오류 블록만 재전송"},{"term":"Adaptive ARQ","desc":"전송 효율을 위해 블록 길이를 동적으로 바꿈"}],"memo":"ARQ는 ‘정지-대기, Go-Back-N, 선택적, 적응적’ 네 가지."}},{"id":"written-2025-3-70","no":70,"unit":"프로그래밍 언어 활용","q":"커널에서 지원되는 스레드에 비해 사용자 수준에서 지원되는 스레드(thread)가 가지는 장점으로 옳은 것은?","choices":["여러 스레드가 동시에 커널에 접근할 수 있어 여러 스레드가 시스템 호출을 동시에 사용할 수 있다.","한 프로세스가 운영체제를 호출하더라도 전체 프로세스가 대기할 필요가 없어 시스템 성능을 높일 수 있다.","커널 모드로 전환하지 않고도 스레드 교환이 가능하여 오버헤드가 줄어든다.","각 스레드를 개별적으로 관리할 수 있어 스레드의 독립적인 스케줄링이 가능하다."],"ans":3,"exp":{"concept":"사용자 수준 스레드는 커널이 모르게 사용자 영역의 스레드 라이브러리가 관리한다. 스레드를 바꿀 때 커널 모드로 들어갈 필요가 없어 빠르고 오버헤드가 적다. 대신 한 스레드가 시스템 호출로 멈추면 같은 프로세스의 다른 스레드도 함께 멈춘다. 커널 수준 스레드는 커널이 직접 관리해 이런 문제가 없는 대신 전환 비용이 크다.","choices":[{"verdict":"오답","why":"여러 스레드가 동시에 커널에 접근하고 시스템 호출을 동시에 쓸 수 있는 것은 커널 수준 스레드의 장점이다."},{"verdict":"오답","why":"한 스레드가 운영체제를 호출해도 프로세스 전체가 대기하지 않는 것은 커널 수준 스레드의 장점이다. 사용자 수준 스레드는 이때 전체 프로세스가 멈춘다."},{"verdict":"정답","why":"커널 모드로 전환하지 않고 스레드를 교환할 수 있어 오버헤드가 줄어드는 것이 사용자 수준 스레드의 장점이므로 정답이다."},{"verdict":"오답","why":"커널이 각 스레드를 개별적으로 관리해 독립적으로 스케줄링할 수 있는 것은 커널 수준 스레드의 장점이다."}],"keywords":[{"term":"사용자 수준 스레드","desc":"사용자 라이브러리가 관리, 전환이 빠름, 시스템 호출 시 전체 프로세스 대기"},{"term":"커널 수준 스레드","desc":"커널이 관리, 개별 스케줄링 가능, 전환 오버헤드 큼"},{"term":"모드 전환","desc":"사용자 모드와 커널 모드 사이를 오가는 것으로, 비용이 듦"}],"memo":"사용자 수준 스레드의 장점은 ‘커널을 안 거쳐서 빠르다’ 하나다. 나머지 동시성 장점은 모두 커널 수준 스레드 쪽이다."}},{"id":"written-2025-3-71","no":71,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램을 실행했을 때의 실행 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nint main(int argc, char* argv[]) {\n    int a = 5, b = 3, c = 12;\n    int t1, t2, t3;\n    t1 = a &amp;&amp; b;\n    t2 = a || b;\n    t3 = !c;\n    printf(\"%d\", t1 + t2 + t3);\n    return 0;\n}</code></pre>","choices":["０","２","５","14"],"ans":2,"exp":{"concept":"C언어에서 0은 거짓, 0이 아닌 값은 모두 참이다. 논리 연산(&&, ||, !)의 결과는 참이면 1, 거짓이면 0이다.","choices":[{"verdict":"오답","why":"t1과 t2가 모두 1이므로 합이 0이 될 수 없다."},{"verdict":"정답","why":"t1 = 5 && 3 → 둘 다 0이 아니므로 1, t2 = 5 || 3 → 1, t3 = !12 → 12는 참이므로 부정하면 0이다. 1 + 1 + 0 = 2가 출력된다."},{"verdict":"오답","why":"논리 연산 결과는 0 또는 1뿐이라 세 값의 합은 최대 3이므로 5가 나올 수 없다."},{"verdict":"오답","why":"논리 연산자를 산술 연산처럼 계산해도 14가 나올 근거가 없다. 논리 연산 결과는 0 또는 1이다."}],"keywords":[{"term":"&& (논리곱)","desc":"둘 다 참이면 1, 아니면 0"},{"term":"|| (논리합)","desc":"하나라도 참이면 1, 아니면 0"},{"term":"! (논리 부정)","desc":"참(0이 아닌 값)이면 0, 거짓(0)이면 1"}],"memo":"논리 연산자의 결과는 무조건 0 아니면 1이다. 원래 값(5, 3, 12)이 그대로 나오지 않는다."}},{"id":"written-2025-3-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 중 Java의 출력 함수에 해당하지 않는 것은?","choices":["System.out.println( )","System.out.printf( )","System.out.printing( )","System.out.print( )"],"ans":3,"exp":{"concept":"Java에서 콘솔에 출력할 때는 System.out 객체의 메서드를 쓴다. print()는 줄바꿈 없이, println()은 출력 후 줄바꿈, printf()는 형식 지정자로 서식을 맞춰 출력한다.","choices":[{"verdict":"오답","why":"System.out.println()은 출력 후 줄을 바꾸는 Java 출력 메서드다."},{"verdict":"오답","why":"System.out.printf()는 %d, %s 같은 서식 지정자로 형식을 맞춰 출력하는 Java 출력 메서드다."},{"verdict":"정답","why":"System.out.printing()이라는 메서드는 존재하지 않으므로 정답이다."},{"verdict":"오답","why":"System.out.print()는 줄바꿈 없이 출력하는 Java 출력 메서드다."}],"keywords":[{"term":"print()","desc":"줄바꿈 없이 출력"},{"term":"println()","desc":"출력 후 줄바꿈"},{"term":"printf()","desc":"서식 지정자를 사용한 형식 출력"}],"memo":"Java 출력은 print, println, printf 세 가지. ‘ing’가 붙은 메서드는 없다."}},{"id":"written-2025-3-73","no":73,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 가운데 네트워크 계층에 관한 설명으로 옳지 않은 것은?","choices":["패킷에 발신지와 목적지의 논리 주소를 덧붙인다.","한 노드에서 다른 노드로 프레임을 전송할 책임을 진다.","라우터나 교환기는 패킷 전달을 위해 경로를 지정하거나 교환 기능을 제공한다.","발신지에서 최종 목적지까지 패킷을 전달할 책임을 진다."],"ans":2,"exp":{"concept":"OSI 7계층에서 네트워크 계층(3계층)은 출발지에서 최종 목적지까지 패킷을 전달하는 일을 맡는다. 논리 주소(IP 주소)를 붙이고 라우터가 경로를 정한다. 바로 옆 노드까지 프레임을 전달하는 일은 데이터 링크 계층(2계층)의 책임이다.","choices":[{"verdict":"오답","why":"네트워크 계층은 패킷에 발신지와 목적지의 논리 주소(IP 주소)를 붙인다."},{"verdict":"정답","why":"한 노드에서 다음 노드로 프레임을 전송하는 것은 데이터 링크 계층의 역할이므로 네트워크 계층에 대한 설명으로 옳지 않다."},{"verdict":"오답","why":"네트워크 계층에서 라우터는 경로를 지정하고 교환 기능을 제공한다."},{"verdict":"오답","why":"네트워크 계층은 발신지에서 최종 목적지까지 패킷을 전달할 책임을 진다."}],"keywords":[{"term":"네트워크 계층","desc":"패킷, 논리 주소(IP), 라우팅, 종단 간 전달"},{"term":"데이터 링크 계층","desc":"프레임, 물리 주소(MAC), 인접 노드 간 전달, 흐름·오류 제어"},{"term":"라우터","desc":"네트워크 계층 장비, 최적 경로 선택"}],"memo":"‘프레임’이라는 단어가 나오면 데이터 링크 계층이다. 네트워크 계층은 ‘패킷’."}},{"id":"written-2025-3-74","no":74,"unit":"프로그래밍 언어 활용","q":"IPv4 데이터그램의 단편화(Fragmentation) 및 재결합(Reassembly)에 관한 설명 중 옳지 않은 것은?","choices":["각 단편의 헤더에는 재결합에 필요한 식별자와 단편 위치 정보가 들어 있다.","단편화는 송신 측에서 전송할 데이터를 전송에 적합한 일정 크기의 작은 블록으로 나누는 작업을 말한다.","재결합은 수신 측에서 단편화된 블록들을 원래의 데이터로 다시 모으는 것이다.","단편화를 통해 세분화된 데이터 블록을 프레임이라 부른다."],"ans":4,"exp":{"concept":"IPv4 데이터그램이 경로상 네트워크가 한 번에 보낼 수 있는 크기(MTU)보다 크면 작은 조각으로 나누어 보내는데, 이를 단편화라 한다. 나뉜 조각은 단편(Fragment)이라 부르며, 수신 측은 헤더의 식별자(Identification), 플래그, 단편 오프셋을 보고 원래 데이터로 재결합한다.","choices":[{"verdict":"오답","why":"각 단편의 헤더에는 같은 원본임을 나타내는 식별자와, 원래 데이터에서의 위치를 나타내는 단편 오프셋이 들어 있다."},{"verdict":"오답","why":"단편화는 전송할 데이터를 전송에 알맞은 일정 크기의 작은 블록으로 나누는 작업이다."},{"verdict":"오답","why":"재결합은 수신 측에서 단편들을 원래 데이터로 다시 모으는 것이다."},{"verdict":"정답","why":"단편화로 나뉜 블록은 프레임이 아니라 단편(Fragment)이라 부른다. 프레임은 데이터 링크 계층의 PDU이므로 틀린 설명이다."}],"keywords":[{"term":"단편화(Fragmentation)","desc":"MTU보다 큰 데이터그램을 작은 단편으로 나눔"},{"term":"재결합(Reassembly)","desc":"수신 측에서 단편을 원래 데이터로 합침"},{"term":"단편 오프셋(Fragment Offset)","desc":"단편이 원래 데이터에서 차지하는 위치"},{"term":"MTU","desc":"한 번에 전송할 수 있는 최대 전송 단위"}],"memo":"IP에서 쪼갠 조각은 ‘단편(Fragment)’, 프레임은 2계층 이름이다."}},{"id":"written-2025-3-75","no":75,"unit":"프로그래밍 언어 활용","q":"JAVA의 예외(exception)에 대한 설명으로 옳지 않은 것은?","choices":["존재하지 않는 파일을 읽으려 할 때 발생하는 오류","배열의 인덱스가 범위를 벗어나는 경우에 발생하는 오류","오동작이나 결과에 악영향을 줄 수 있는, 실행 시간 동안 발생하는 오류","문법 오류 때문에 발생하는 것"],"ans":4,"exp":{"concept":"Java의 예외(Exception)는 프로그램이 실행되는 도중에 생기는 오류다. 없는 파일 열기, 배열 범위 초과, 0으로 나누기 등이 대표적이며 try-catch로 처리할 수 있다. 문법 오류는 컴파일 단계에서 걸려 실행조차 되지 않으므로 예외가 아니다.","choices":[{"verdict":"오답","why":"존재하지 않는 파일을 읽으려 할 때는 FileNotFoundException 예외가 발생한다."},{"verdict":"오답","why":"배열 인덱스가 범위를 벗어나면 ArrayIndexOutOfBoundsException 예외가 발생한다."},{"verdict":"오답","why":"예외는 실행 시간 동안 발생해 오동작이나 잘못된 결과를 일으킬 수 있는 오류다."},{"verdict":"정답","why":"문법 오류는 컴파일할 때 발견되는 컴파일 오류로, 실행 중 발생하는 예외가 아니므로 옳지 않다."}],"keywords":[{"term":"예외(Exception)","desc":"실행 중 발생하는 오류, try-catch로 처리 가능"},{"term":"컴파일 오류","desc":"문법 오류로 컴파일 단계에서 발견, 실행 불가"},{"term":"try-catch-finally","desc":"예외 발생 가능 코드, 예외 처리, 항상 실행할 코드"}],"memo":"예외는 ‘실행 중’에 생기는 것. 문법 오류는 실행 전에 걸리므로 예외가 아니다."}},{"id":"written-2025-3-76","no":76,"unit":"프로그래밍 언어 활용","q":"아래 Python 코드의 출력문을 실행한 결과는?<pre class=\"qcode\"><code class=\"language-python\">print(4, 1, 2, sep=',', end='')\nprint(3, 5, sep='/')</code></pre>","choices":["4,1,2<br>3/5","4 1 23/5","4,1,23/5","4 1 2<br>3 5"],"ans":3,"exp":{"concept":"Python의 print()는 여러 값을 sep(기본값 공백)으로 구분해 출력하고, 마지막에 end(기본값 줄바꿈)를 붙인다. sep과 end를 바꾸면 구분자와 끝 문자가 달라진다.","choices":[{"verdict":"오답","why":"첫 print의 end=''로 줄바꿈이 붙지 않으므로 3/5가 다음 줄로 내려가지 않는다."},{"verdict":"오답","why":"첫 print는 sep=','이므로 숫자 사이가 공백이 아니라 쉼표로 구분된다."},{"verdict":"정답","why":"첫 print는 4,1,2를 출력하고 end=''로 줄바꿈 없이 끝난다. 이어서 두 번째 print가 sep='/'로 3/5를 출력하므로 결과는 4,1,23/5다."},{"verdict":"오답","why":"sep과 end를 바꿨으므로 기본값(공백 구분, 줄바꿈)으로 출력되지 않는다."}],"keywords":[{"term":"sep","desc":"여러 값 사이에 넣는 구분자, 기본값은 공백"},{"term":"end","desc":"출력 끝에 붙는 문자, 기본값은 줄바꿈"},{"term":"print()","desc":"Python의 표준 출력 함수"}],"memo":"end=''이면 다음 print가 같은 줄에 바로 이어 붙는다. 2와 3 사이에 아무것도 없다는 점을 놓치지 않는다."}},{"id":"written-2025-3-77","no":77,"unit":"프로그래밍 언어 활용","q":"프로세스 적재 정책에 관한 설명 중 틀린 것은?","choices":["반복, 스택, 부프로그램은 시간 지역성(Temporal Locality)과 관련된다.","스레싱(Thrashing) 현상을 방지하려면 각 프로세스가 필요로 하는 프레임을 제공할 수 있어야 한다.","공간 지역성(Spatial Locality)은 프로세스가 어떤 페이지를 참조했을 때 이후 가상주소 공간상 그 페이지와 인접한 페이지들을 참조할 가능성이 높다는 것을 의미한다.","일반적으로 페이지 교환에 보내는 시간보다 프로세스 수행에 보내는 시간이 더 크면 스레싱(Thrashing)이 발생하게 된다."],"ans":4,"exp":{"concept":"지역성(Locality)은 프로세스가 일부 페이지만 집중적으로 참조하는 성질이다. 최근 참조한 곳을 곧 다시 참조하는 시간 지역성과, 근처 주소를 참조하는 공간 지역성이 있다. 스레싱(Thrashing)은 페이지 부재가 너무 잦아 실제 프로세스 수행보다 페이지 교체에 시간을 더 많이 쓰는 현상이다.","choices":[{"verdict":"오답","why":"반복(루프), 스택, 부프로그램, 카운팅·집계 변수는 같은 곳을 반복해 참조하므로 시간 지역성과 관련된다."},{"verdict":"오답","why":"스레싱을 막으려면 각 프로세스가 필요로 하는 만큼의 프레임(워킹 셋)을 제공해야 한다."},{"verdict":"오답","why":"공간 지역성은 어떤 페이지를 참조하면 그 근처 주소의 페이지를 참조할 가능성이 높다는 뜻이다."},{"verdict":"정답","why":"스레싱은 페이지 교환에 쓰는 시간이 프로세스 수행 시간보다 클 때 발생한다. 수행 시간이 더 크면 정상 상태이므로 설명이 거꾸로 되어 있다."}],"keywords":[{"term":"시간 지역성","desc":"최근 참조한 기억 장소를 곧 다시 참조, 반복·스택·부프로그램"},{"term":"공간 지역성","desc":"인접한 기억 장소를 참조, 배열 순회·순차 코드"},{"term":"스레싱(Thrashing)","desc":"페이지 교체 시간이 수행 시간보다 커지는 현상"},{"term":"워킹 셋(Working Set)","desc":"일정 시간 동안 자주 참조하는 페이지 집합"}],"memo":"스레싱 = 일보다 이삿짐(페이지 교체) 나르는 시간이 더 긴 상태."}},{"id":"written-2025-3-78","no":78,"unit":"프로그래밍 언어 활용","q":"프레임워크(Framework)에 관한 설명으로 옳은 것은?","choices":["소프트웨어 아키텍처(Architecture)와 같은 개념이다.","소프트웨어 개발 시 구조가 잡혀 있으므로 확장이 불가능하다.","소프트웨어 구성에 필요한 기본 구조를 제공하여 재사용이 가능하도록 해준다.","모듈화(Modularity)가 불가능하다."],"ans":3,"exp":{"concept":"프레임워크(Framework)는 소프트웨어를 만들 때 필요한 기본 뼈대와 공통 기능을 미리 만들어 제공하는 반제품이다. 개발자는 그 위에 필요한 부분만 채워 넣는다. 모듈화, 재사용성, 확장성, 제어의 역흐름이 특징이다.","choices":[{"verdict":"오답","why":"소프트웨어 아키텍처는 시스템 전체의 구조와 설계 원칙을 말하는 개념이고, 프레임워크는 그 구조를 구현해 재사용할 수 있게 만든 반제품이다. 같은 개념이 아니다."},{"verdict":"오답","why":"프레임워크는 확장성을 특징으로 하므로 확장이 불가능하다는 설명은 틀렸다."},{"verdict":"정답","why":"프레임워크는 소프트웨어 구성에 필요한 기본 구조를 제공해 재사용이 가능하게 하므로 정답이다."},{"verdict":"오답","why":"프레임워크는 모듈화를 특징으로 하므로 모듈화가 불가능하다는 설명은 틀렸다."}],"keywords":[{"term":"프레임워크(Framework)","desc":"기본 구조와 공통 기능을 제공하는 반제품 소프트웨어"},{"term":"프레임워크 특징","desc":"모듈화, 재사용성, 확장성, 제어의 역흐름"},{"term":"제어의 역흐름(IoC)","desc":"개발자 코드가 아니라 프레임워크가 흐름을 제어하는 것"}],"memo":"프레임워크는 집의 골조. 골조가 있으니 재사용·확장·모듈화가 오히려 쉬워진다."}},{"id":"written-2025-3-79","no":79,"unit":"프로그래밍 언어 활용","q":"아래 Python 프로그램을 실행했을 때의 실행 결과로 옳은 것은?<pre class=\"qcode\"><code class=\"language-python\">strA = 'Information Technology'\nstrL = list()\nfor i in range(0, len(strA), 2):\n    strL.append(strA[i])\nfor j in range(len(strL) - 1, 0, -2):\n    print(strL[j], end='')</code></pre>","choices":["lh to","gnTir","ot hl","riTng"],"ans":2,"exp":{"concept":"문자열 인덱스는 0부터 시작한다. range(시작, 끝, 간격)는 끝 값을 포함하지 않는다. 간격이 음수면 거꾸로 센다.","choices":[{"verdict":"오답","why":"lh to는 strL의 원소를 순서대로 따라가서 나오는 문자열이 아니다. strL에는 짝수 인덱스 문자만 들어 있다."},{"verdict":"정답","why":"strA(길이 22)의 짝수 인덱스 문자를 모으면 strL = [I, f, r, a, i, n, T, c, n, l, g](11개)다. j는 10, 8, 6, 4, 2로 내려가며 strL[10]=g, strL[8]=n, strL[6]=T, strL[4]=i, strL[2]=r을 출력하므로 gnTir이 된다."},{"verdict":"오답","why":"ot hl은 strL에서 뽑은 문자로 이루어진 문자열이 아니다. 공백은 홀수 인덱스(11번)에 있어 strL에 들어가지 않는다."},{"verdict":"오답","why":"riTng는 출력 순서를 거꾸로 한 것이다. 두 번째 반복문은 큰 인덱스부터 내려가므로 g가 먼저 나온다."}],"keywords":[{"term":"range(start, stop, step)","desc":"start부터 stop 직전까지 step 간격으로 생성"},{"term":"음수 step","desc":"큰 수에서 작은 수 방향으로 감소, stop은 포함하지 않음"},{"term":"문자열 인덱싱","desc":"0부터 시작, 공백도 한 글자로 셈"}],"memo":"range(10, 0, -2)는 10, 8, 6, 4, 2. 끝값 0은 포함되지 않아 strL[0]인 I는 출력되지 않는다."}},{"id":"written-2025-3-80","no":80,"unit":"프로그래밍 언어 활용","q":"다음 Java 프로그램을 실행했을 때 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-java\">public class Test {\n    public static void main(String[] args) {\n        int x = 7, y = 0;\n        while(x-- &gt; 0) {\n            if (x%3 == 0)\n                continue;\n            y++;\n        }\n        System.out.print(y);\n    }\n}</code></pre>","choices":["0","4","5","7"],"ans":2,"exp":{"concept":"x--는 후위 감소 연산이라 먼저 현재 x 값으로 비교한 뒤 x를 1 줄인다. continue를 만나면 아래 문장을 건너뛰고 다음 반복 조건 검사로 간다.","choices":[{"verdict":"오답","why":"반복문 안에서 x는 6부터 0까지 7번 바뀌며, 3의 배수가 아닐 때마다 y가 증가하므로 0이 아니다."},{"verdict":"정답","why":"조건 검사 7 > 0, 6 > 0, …, 1 > 0이 참인 동안 본문의 x는 6, 5, 4, 3, 2, 1, 0이 된다. 이 중 x%3 == 0인 6, 3, 0에서는 continue로 건너뛰고, 5, 4, 2, 1에서만 y++가 실행되어 y = 4가 출력된다."},{"verdict":"오답","why":"x가 3의 배수인 6, 3, 0 세 번은 continue로 건너뛰므로 y는 5가 될 수 없다."},{"verdict":"오답","why":"반복은 7번이지만 그중 3번은 continue로 y++를 건너뛰므로 7이 아니다."}],"keywords":[{"term":"후위 감소(x--)","desc":"현재 값을 먼저 사용한 뒤 1 감소"},{"term":"전위 감소(--x)","desc":"먼저 1 감소한 뒤 그 값을 사용"},{"term":"continue","desc":"남은 본문을 건너뛰고 다음 반복으로 이동"}],"memo":"x-- > 0에서 비교는 감소 전 값으로, 본문에서는 감소 후 값을 쓴다. 본문의 x는 6~0이다."}},{"id":"written-2025-3-81","no":81,"unit":"정보시스템 구축 관리","q":"프로젝트 일정 관리에서 사용되는 PERT 차트에 관한 설명으로 옳은 것은?","choices":["수평 막대의 길이가 각 작업의 기간을 의미한다.","각 작업이 언제 시작되고 언제 종료되는지의 일정을 막대 도표로 나타낸다.","작업 간의 상호 관련성, 결정 경로, 경계 시간, 자원 할당 등을 나타낸다.","시간선(Time-Line) 차트라고 부르기도 한다."],"ans":3,"exp":{"concept":"PERT(Program Evaluation and Review Technique) 차트는 작업들을 노드와 화살표로 연결한 네트워크 그림으로, 작업 사이의 선후 관계와 결정 경로, 경계 시간, 자원 할당 등을 보여 준다. 막대로 일정을 나타내는 것은 간트 차트(Gantt Chart)다.","choices":[{"verdict":"오답","why":"수평 막대의 길이가 작업 기간을 뜻하는 것은 간트 차트의 특징이다."},{"verdict":"오답","why":"작업의 시작과 종료 일정을 막대 도표로 나타내는 것은 간트 차트다."},{"verdict":"정답","why":"PERT 차트는 작업 간의 상호 관련성, 결정 경로, 경계 시간, 자원 할당 등을 나타내므로 정답이다."},{"verdict":"오답","why":"시간선(Time-Line) 차트라고도 부르는 것은 간트 차트다."}],"keywords":[{"term":"PERT","desc":"작업 간 관계를 네트워크로 표현, 낙관·비관·중간치 추정 사용"},{"term":"CPM","desc":"임계 경로(Critical Path)를 찾아 일정 관리"},{"term":"간트 차트(Gantt Chart)","desc":"작업 일정을 수평 막대로 표시, 시간선 차트"}],"memo":"‘막대·시간선’이 보이면 간트 차트, ‘관계·경로·네트워크’면 PERT."}},{"id":"written-2025-3-82","no":82,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 비용산정 기법은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>조직 내 경험이 많은 두 명 이상의 전문가에게 비용 산정을 의뢰하는 기법이다.</li><li>가장 편리하고 신속하게 비용을 산정할 수 있고, 의뢰자로부터 믿음을 얻을 수 있다.</li><li>개인적이며 주관적일 수 있다.</li></ul></div>","choices":["Putnam 모형","LOC 기법","전문가 감정 기법","델파이 기법"],"ans":3,"exp":{"concept":"하향식 비용 산정 기법에는 전문가 감정 기법과 델파이 기법이 있다. 전문가 감정 기법은 경험 많은 전문가 두 명 이상에게 비용 산정을 맡기는 방법으로, 빠르고 편하지만 개인적·주관적일 수 있다. 델파이 기법은 이 주관성을 줄이려고 조정자를 두고 여러 전문가의 의견을 모으는 방법이다.","choices":[{"verdict":"오답","why":"Putnam 모형은 소프트웨어 생명주기 전 과정의 노력 분포를 가정해 비용을 산정하는 수학적 모형이다."},{"verdict":"오답","why":"LOC(Lines Of Code) 기법은 원시 코드 라인 수의 낙관치, 중간치, 비관치로 예측치를 구해 비용을 산정하는 상향식 기법이다."},{"verdict":"정답","why":"경험 많은 두 명 이상의 전문가에게 의뢰하고, 빠르지만 주관적일 수 있다는 설명은 전문가 감정 기법이므로 정답이다."},{"verdict":"오답","why":"델파이 기법은 전문가 감정 기법의 주관적 편견을 보완하려고 조정자 한 명과 여러 전문가의 의견을 종합하는 기법이다."}],"keywords":[{"term":"전문가 감정 기법","desc":"경험 많은 전문가 두 명 이상이 산정, 빠르지만 주관적"},{"term":"델파이 기법","desc":"조정자를 두고 여러 전문가 의견을 종합해 주관성 보완"},{"term":"LOC 기법","desc":"(낙관치 + 4 × 중간치 + 비관치) ÷ 6으로 예측"},{"term":"Putnam 모형","desc":"Rayleigh-Norden 곡선 기반 비용 산정"}],"memo":"‘주관적일 수 있다’면 전문가 감정, ‘조정자’가 나오면 델파이."}},{"id":"written-2025-3-83","no":83,"unit":"정보시스템 구축 관리","q":"전자 칩처럼 소프트웨어 부품, 즉 블록(모듈)을 만들어 끼워 맞추는 방식으로 소프트웨어를 완성하는 재사용 방법은?","choices":["합성 중심","구조 중심","분리 중심","생성 중심"],"ans":1,"exp":{"concept":"소프트웨어 재사용 방법은 합성 중심과 생성 중심으로 나뉜다. 합성 중심(Composition-Based)은 전자 칩처럼 모듈(블록)을 만들어 끼워 맞추는 블록 구성 방법이고, 생성 중심(Generation-Based)은 추상화된 패턴을 구체화해 소프트웨어를 만드는 패턴 구성 방법이다.","choices":[{"verdict":"정답","why":"블록(모듈)을 만들어 끼워 맞추는 방식은 합성 중심(블록 구성 방법)이므로 정답이다."},{"verdict":"오답","why":"구조 중심은 소프트웨어 재사용 방법의 분류에 해당하지 않는다."},{"verdict":"오답","why":"분리 중심은 소프트웨어 재사용 방법의 분류에 해당하지 않는다."},{"verdict":"오답","why":"생성 중심은 추상화된 형태의 패턴을 구체화해 프로그램을 만드는 패턴 구성 방법이다."}],"keywords":[{"term":"합성 중심(Composition-Based)","desc":"블록(모듈)을 조립하는 블록 구성 방법"},{"term":"생성 중심(Generation-Based)","desc":"추상화된 패턴을 구체화하는 패턴 구성 방법"},{"term":"소프트웨어 재사용","desc":"이미 만든 소프트웨어를 다시 사용해 생산성과 품질을 높이는 것"}],"memo":"레고 블록을 ‘합쳐서’ 만들면 합성 중심, 설계도(패턴)로 ‘찍어 내면’ 생성 중심."}},{"id":"written-2025-3-84","no":84,"unit":"정보시스템 구축 관리","q":"다음에서 설명하는 스토리지 시스템은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>하드디스크 등의 데이터 저장장치를 호스트버스 어댑터에 직접 연결하는 방식</li><li>저장장치와 호스트 기기 사이에 네트워크 디바이스가 있어서는 안 되며, 직접 연결하는 방식으로 구성</li></ul></div>","choices":["NFC","DAS","NAS","N-SCREEN"],"ans":2,"exp":{"concept":"스토리지 연결 방식은 DAS, NAS, SAN이 있다. DAS(Direct Attached Storage)는 저장 장치를 서버에 케이블로 직접 연결하는 방식으로, 중간에 네트워크 장비가 없다.","choices":[{"verdict":"오답","why":"NFC(Near Field Communication)는 가까운 거리에서 쓰는 비접촉 무선 통신 기술이다."},{"verdict":"정답","why":"저장 장치를 호스트 버스 어댑터에 직접 연결하고 중간에 네트워크 장치를 두지 않는 방식은 DAS이므로 정답이다."},{"verdict":"오답","why":"NAS(Network Attached Storage)는 저장 장치를 네트워크에 연결해 여러 서버가 파일 단위로 공유하는 방식이다."},{"verdict":"오답","why":"N-Screen은 하나의 콘텐츠를 PC, TV, 스마트폰 등 여러 기기에서 이어서 볼 수 있게 하는 서비스다."}],"keywords":[{"term":"DAS","desc":"서버에 저장 장치를 직접 연결"},{"term":"NAS","desc":"네트워크에 연결된 파일 서버형 저장 장치"},{"term":"SAN","desc":"전용 고속 네트워크(파이버 채널 등)로 서버와 저장 장치를 연결"}],"memo":"D는 Direct(직접), N은 Network(네트워크). ‘네트워크 장치가 있어서는 안 된다’면 DAS다."}},{"id":"written-2025-3-85","no":85,"unit":"정보시스템 구축 관리","q":"TCP/IP 기반 네트워크에서 동작하며 발행-구독 방식의 메시징 프로토콜로서, 최근 IoT 환경에서 자주 활용되고 있는 프로토콜은?","choices":["MTSP","Zigbee","MQTT","MLFQ"],"ans":3,"exp":{"concept":"MQTT(Message Queuing Telemetry Transport)는 TCP/IP 위에서 동작하는 가벼운 메시징 프로토콜이다. 메시지를 보내는 쪽(발행자)이 주제(Topic)로 메시지를 올리면, 그 주제를 구독한 쪽이 브로커를 통해 받는 발행-구독(Publish-Subscribe) 방식이다. 저전력·저대역폭이라 IoT에 많이 쓰인다.","choices":[{"verdict":"오답","why":"MTSP는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"지그비(Zigbee)는 IEEE 802.15.4 기반의 저전력 근거리 무선 통신 기술로, TCP/IP 기반 발행-구독 메시징 프로토콜이 아니다."},{"verdict":"정답","why":"MQTT는 TCP/IP 기반 발행-구독 방식의 경량 메시징 프로토콜로, IoT에서 널리 쓰이므로 정답이다."},{"verdict":"오답","why":"MLFQ(Multi-Level Feedback Queue)는 운영체제의 다단계 피드백 큐 CPU 스케줄링 기법이다."}],"keywords":[{"term":"MQTT","desc":"IoT용 경량 발행-구독 메시징 프로토콜"},{"term":"발행-구독(Publish-Subscribe)","desc":"발행자와 구독자가 브로커를 통해 주제별로 메시지를 주고받는 방식"},{"term":"Zigbee","desc":"저전력 근거리 무선 통신, IEEE 802.15.4 기반"}],"memo":"‘발행-구독’, ‘IoT’ 두 단어가 함께 나오면 MQTT다."}},{"id":"written-2025-3-86","no":86,"unit":"정보시스템 구축 관리","q":"접근통제에 관한 설명 중 틀린 것은?","choices":["역할기반 접근통제는 사용자의 역할에 따라 접근 권한을 부여하는 방식이다.","임의 접근통제는 주체와 객체의 등급을 비교해 접근 권한을 부여하는 방식이다.","데이터가 저장된 객체와 이를 사용하고자 하는 주체 간의 정보 흐름을 제한하는 것이다.","데이터를 통제함으로써 자원에 대한 불법적인 접근 및 파괴를 예방한다."],"ans":2,"exp":{"concept":"접근 통제는 주체(사용자)가 객체(데이터)에 접근하는 것을 제한해 불법 접근과 파괴를 막는 것이다. 임의 접근 통제(DAC)는 사용자의 신분(신원)에 따라, 강제 접근 통제(MAC)는 주체와 객체의 보안 등급을 비교해, 역할 기반 접근 통제(RBAC)는 사용자의 역할에 따라 권한을 준다.","choices":[{"verdict":"오답","why":"역할 기반 접근 통제(RBAC)는 사용자의 역할에 따라 접근 권한을 부여한다."},{"verdict":"정답","why":"주체와 객체의 등급을 비교해 권한을 주는 것은 강제 접근 통제(MAC)다. 임의 접근 통제(DAC)는 사용자의 신분(신원)에 따라 권한을 준다. 따라서 틀린 설명이다."},{"verdict":"오답","why":"접근 통제는 데이터가 저장된 객체와 이를 사용하려는 주체 사이의 정보 흐름을 제한하는 것이다."},{"verdict":"오답","why":"접근 통제는 데이터를 통제해 자원에 대한 불법적인 접근과 파괴를 예방한다."}],"keywords":[{"term":"DAC(임의 접근 통제)","desc":"사용자 신원에 따라 권한 부여, 소유자가 권한 지정"},{"term":"MAC(강제 접근 통제)","desc":"주체와 객체의 보안 등급을 비교해 권한 부여"},{"term":"RBAC(역할 기반 접근 통제)","desc":"사용자의 역할에 따라 권한 부여"}],"memo":"등급(Level)을 비교하면 강제(MAC), 신분(Identity)이면 임의(DAC), 역할(Role)이면 RBAC."}},{"id":"written-2025-3-87","no":87,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 소프트웨어 개발 방법론은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>기존 시스템이나 소프트웨어를 구성하고 있는 컴포넌트를 조합해 새로운 애플리케이션 하나를 만들어 내는 방법론이다.</li><li>컴포넌트의 재사용(Reusability)이 가능하므로 시간과 노력을 절감할 수 있다.</li></ul></div>","choices":["Agile 방법론","CBD 방법론","구조적 방법론","정보공학 방법론"],"ans":2,"exp":{"concept":"CBD(Component Based Development) 방법론은 미리 만들어진 컴포넌트(부품)를 조합해 새 애플리케이션을 만드는 방법이다. 컴포넌트를 재사용하므로 개발 시간과 노력이 줄고 유지보수가 쉬워진다.","choices":[{"verdict":"오답","why":"애자일(Agile) 방법론은 짧은 주기로 반복 개발하며 고객과의 협업과 변화 대응을 중시하는 방법론이다."},{"verdict":"정답","why":"컴포넌트를 조합해 애플리케이션을 만들고 재사용성으로 시간과 노력을 줄이는 것은 CBD 방법론이므로 정답이다."},{"verdict":"오답","why":"구조적 방법론은 기능에 따라 시스템을 하향식으로 분할하는 처리(절차) 중심 방법론이다."},{"verdict":"오답","why":"정보공학 방법론은 기업 전체 관점에서 정보 시스템을 계획·분석·설계·구축하는 데이터 중심 방법론이다."}],"keywords":[{"term":"CBD 방법론","desc":"컴포넌트를 조합해 개발, 재사용성 높음"},{"term":"구조적 방법론","desc":"기능 중심 하향식 분할, DFD 사용"},{"term":"정보공학 방법론","desc":"기업 전체를 대상으로 하는 데이터 중심 방법론"},{"term":"컴포넌트(Component)","desc":"독립적으로 재사용 가능한 소프트웨어 부품"}],"memo":"‘컴포넌트 조합’ = CBD. 이름에 답(Component Based)이 들어 있다."}},{"id":"written-2025-3-88","no":88,"unit":"정보시스템 구축 관리","q":"다음에서 설명하고 있는 것은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>블록체인(Blockchain) 개발 환경을 클라우드 형태로 제공하는 서비스 개념</li><li>블록체인 네트워크에서 노드를 추가하거나 제거하기가 용이</li><li>블록체인의 기본 인프라를 추상화하여 블록체인 응용프로그램을 개발할 수 있게 하는 클라우드 컴퓨팅 플랫폼</li></ul></div>","choices":["OTT","SDDC","BaaS","Wi-SUN"],"ans":3,"exp":{"concept":"BaaS(Blockchain as a Service)는 블록체인 개발 환경을 클라우드 서비스로 빌려 주는 개념이다. 노드 추가·제거 같은 블록체인 인프라 관리를 서비스 제공자가 맡아 주므로, 개발자는 블록체인 응용 프로그램 개발에 집중할 수 있다.","choices":[{"verdict":"오답","why":"OTT(Over The Top)는 인터넷으로 영화, 방송 등 동영상 콘텐츠를 제공하는 서비스다."},{"verdict":"오답","why":"SDDC(Software Defined Data Center)는 데이터센터의 컴퓨팅, 네트워크, 스토리지 등 모든 자원을 소프트웨어로 가상화해 관리하는 데이터센터다."},{"verdict":"정답","why":"블록체인 개발 환경을 클라우드로 제공하는 서비스는 BaaS(Blockchain as a Service)이므로 정답이다."},{"verdict":"오답","why":"Wi-SUN(Wireless Smart Utility Network)은 스마트 그리드 등 원격 검침에 쓰이는 장거리 저전력 무선 통신 기술이다."}],"keywords":[{"term":"BaaS","desc":"Blockchain as a Service, 클라우드 기반 블록체인 개발 환경"},{"term":"SDDC","desc":"모든 자원을 소프트웨어로 가상화한 데이터센터"},{"term":"OTT","desc":"인터넷 기반 동영상 서비스"}],"memo":"클라우드 서비스 이름은 ‘○aaS(○ as a Service)’. 블록체인(B)을 서비스로 주면 BaaS."}},{"id":"written-2025-3-89","no":89,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 프레임워크를 적용했을 때 기대할 수 있는 효과와 거리가 먼 것은?","choices":["변경 용이성","품질 보증","개발 용이성","기술 종속성"],"ans":4,"exp":{"concept":"소프트웨어 개발 프레임워크는 공통 기능과 기본 구조를 미리 만들어 제공하므로 품질이 보장되고, 개발과 변경이 쉬워지며, 개발 코드가 줄고 시스템 복잡도가 낮아진다. 특정 기술에 묶이는 기술 종속성은 기대 효과가 아니라 오히려 피해야 할 점이다.","choices":[{"verdict":"오답","why":"프레임워크는 구조가 표준화되어 있어 변경이 쉬워지는 변경 용이성 효과가 있다."},{"verdict":"오답","why":"검증된 공통 기능을 쓰므로 품질 보증 효과가 있다."},{"verdict":"오답","why":"기본 구조가 제공되어 개발이 쉬워지는 개발 용이성 효과가 있다."},{"verdict":"정답","why":"기술 종속성은 특정 기술에 얽매이는 것이라 프레임워크를 적용해 얻으려는 효과가 아니므로 거리가 멀다."}],"keywords":[{"term":"프레임워크 기대 효과","desc":"품질 보증, 개발 용이성, 변경 용이성, 시스템 복잡도 감소, 개발 코드 최소화"},{"term":"프레임워크 특징","desc":"모듈화, 재사용성, 확장성, 제어의 역흐름"}],"memo":"‘종속성’은 설계에서 거의 언제나 줄여야 할 대상이다. 기대 효과 목록에 나오면 오답이다."}},{"id":"written-2025-3-90","no":90,"unit":"정보시스템 구축 관리","q":"컴퓨터 사용자의 키보드 움직임을 탐지하여 ID, 패스워드 등 개인의 중요한 정보를 몰래 빼내는 해킹 공격은?","choices":["Worm","Key Logger Attack","Rollback","Zombie Worm"],"ans":2,"exp":{"concept":"키 로거 공격(Key Logger Attack)은 사용자의 키보드 입력을 몰래 기록해 ID, 패스워드, 카드 번호 같은 중요 정보를 빼내는 공격이다.","choices":[{"verdict":"오답","why":"웜(Worm)은 네트워크를 통해 스스로를 복제하며 퍼지는 악성 프로그램이다."},{"verdict":"정답","why":"키보드 움직임을 탐지해 ID, 패스워드 등을 빼내는 공격은 키 로거 공격(Key Logger Attack)이므로 정답이다."},{"verdict":"오답","why":"롤백(Rollback)은 작업을 취소하고 이전 상태로 되돌리는 것으로, 해킹 공격이 아니다."},{"verdict":"오답","why":"Zombie Worm은 키보드 입력을 가로채는 공격을 가리키는 표준 용어가 아니다. 좀비(Zombie)는 악성코드에 감염되어 원격으로 조종되는 컴퓨터를 말한다."}],"keywords":[{"term":"키 로거(Key Logger)","desc":"키보드 입력을 몰래 기록해 정보를 탈취"},{"term":"웜(Worm)","desc":"네트워크로 스스로 복제·전파하는 악성 프로그램"},{"term":"좀비(Zombie) PC","desc":"악성코드에 감염되어 공격자가 원격 조종하는 컴퓨터"}],"memo":"‘키보드’ = Key Logger. 이름 그대로 키(Key)를 기록(Log)한다."}},{"id":"written-2025-3-91","no":91,"unit":"정보시스템 구축 관리","q":"크래커가 침입해 백도어를 만들어 두거나 설정 파일을 변경했을 때 이를 분석하는 데 사용하는 도구는?","choices":["cron","tcpdump","netcat","tripwire"],"ans":4,"exp":{"concept":"트립와이어(Tripwire)는 파일의 해시값 같은 무결성 정보를 미리 저장해 두고, 나중에 비교해 바뀐 파일을 찾아내는 무결성 점검 도구다. 침입자가 백도어를 심거나 설정 파일을 바꿨는지 분석할 때 쓴다.","choices":[{"verdict":"오답","why":"cron은 정해진 시간에 작업을 자동 실행하도록 예약하는 유닉스·리눅스 작업 스케줄러다."},{"verdict":"오답","why":"tcpdump는 네트워크 인터페이스를 지나가는 패킷을 캡처해 보여 주는 패킷 분석 도구다."},{"verdict":"오답","why":"netcat은 TCP·UDP 연결로 데이터를 읽고 쓰는 네트워크 유틸리티다."},{"verdict":"정답","why":"tripwire는 파일 변경을 탐지해 백도어 생성이나 설정 파일 변경을 분석하는 무결성 점검 도구이므로 정답이다."}],"keywords":[{"term":"Tripwire","desc":"파일 무결성 점검, 변경된 파일 탐지"},{"term":"tcpdump","desc":"네트워크 패킷 캡처·분석"},{"term":"cron","desc":"작업 예약 실행 스케줄러"},{"term":"netcat","desc":"TCP·UDP로 데이터를 읽고 쓰는 네트워크 도구"}],"memo":"트립와이어(Tripwire)는 ‘건드리면 울리는 인계철선’. 파일을 건드리면 알아챈다."}},{"id":"written-2025-3-92","no":92,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 방법론 가운데 애자일(Agile) 방법론의 특징으로 가장 거리가 먼 것은?","choices":["소프트웨어 개발에 참여하는 구성원 간의 의사소통을 중시","프로젝트 상황에 따라 주기적으로 조정","각 단계의 결과를 완전히 확인한 뒤 다음 단계로 진행","환경 변화에 즉시 대응"],"ans":3,"exp":{"concept":"애자일(Agile) 방법론은 짧은 주기로 개발을 반복하며 고객과 소통하고, 변화에 빠르게 대응한다. 한 단계를 완전히 끝내고 확인한 뒤에야 다음 단계로 넘어가는 것은 폭포수(Waterfall) 모형의 특징이다.","choices":[{"verdict":"오답","why":"애자일은 구성원 간의 의사소통을 중시한다."},{"verdict":"오답","why":"애자일은 프로젝트 상황에 따라 주기적으로 계획과 진행을 조정한다."},{"verdict":"정답","why":"각 단계의 결과를 완전히 확인한 뒤 다음 단계로 진행하는 것은 폭포수 모형의 특징이므로 애자일과 거리가 멀다."},{"verdict":"오답","why":"애자일은 환경 변화에 즉시 대응하는 것을 중시한다."}],"keywords":[{"term":"애자일 선언문 가치","desc":"프로세스·도구보다 개인과 상호작용, 문서보다 작동하는 소프트웨어, 계약 협상보다 고객 협력, 계획 준수보다 변화 대응"},{"term":"폭포수 모형","desc":"각 단계를 끝내고 검토한 뒤 다음 단계로 진행하는 선형 순차 모형"},{"term":"애자일 종류","desc":"XP, 스크럼, 칸반, 린, 크리스탈 등"}],"memo":"‘완전히 끝내고 다음 단계’ = 폭포수. 애자일은 짧게 반복한다."}},{"id":"written-2025-3-93","no":93,"unit":"정보시스템 구축 관리","q":"물리적인 사물과 컴퓨터에 동일하게 표현되는 가상의 모델로서, 실제 물리적인 자산 대신 소프트웨어로 가상화하여 실제 자산의 특성에 관한 정확한 정보를 얻을 수 있으며, 자산 최적화, 돌발사고 최소화, 생산성 증가 등 설계에서 제조, 서비스에 이르는 모든 과정의 효율성을 높일 수 있는 모델은?","choices":["N-Screen","실행 시간","디지털 트윈","최적화"],"ans":3,"exp":{"concept":"디지털 트윈(Digital Twin)은 현실의 사물(공장, 기계, 도시 등)을 컴퓨터 속에 똑같이 만든 가상 모델이다. 가상 모델로 시뮬레이션해 보면 실제 자산을 건드리지 않고도 상태를 파악하고, 고장을 미리 막고, 효율을 높일 수 있다.","choices":[{"verdict":"오답","why":"N-Screen은 하나의 콘텐츠를 여러 기기에서 끊김 없이 이용하게 하는 서비스다."},{"verdict":"오답","why":"실행 시간은 프로그램이 실행되는 데 걸리는 시간을 뜻하는 일반 용어로, 가상 모델과 관계없다."},{"verdict":"정답","why":"물리적 사물을 컴퓨터에 똑같이 표현한 가상 모델로 효율을 높이는 것은 디지털 트윈이므로 정답이다."},{"verdict":"오답","why":"최적화는 성능이나 효율을 가장 좋게 만드는 일반적인 과정을 뜻할 뿐, 가상 모델을 가리키는 용어가 아니다."}],"keywords":[{"term":"디지털 트윈(Digital Twin)","desc":"현실 사물을 가상 공간에 똑같이 구현한 모델"},{"term":"N-Screen","desc":"여러 기기에서 하나의 콘텐츠를 이어서 이용하는 서비스"}],"memo":"트윈(Twin)은 쌍둥이. 현실 사물의 ‘디지털 쌍둥이’다."}},{"id":"written-2025-3-94","no":94,"unit":"정보시스템 구축 관리","q":"빅데이터 분석 기술 가운데 대량의 데이터를 분석해 데이터 속에 내재된 변수 간의 상호 관계를 규명하고 일정한 패턴을 찾아내는 기법은?","choices":["Data Mining","Zigbee","Digital Twin","Wm-Bus"],"ans":1,"exp":{"concept":"데이터 마이닝(Data Mining)은 대량의 데이터에서 변수 사이의 관계와 숨은 패턴을 찾아내는 분석 기법이다. 광산(Mine)에서 금을 캐듯 데이터 속에서 쓸모 있는 정보를 캐낸다.","choices":[{"verdict":"정답","why":"데이터 마이닝은 대량의 데이터를 분석해 변수 간 상호 관계를 규명하고 패턴을 찾아내는 기법이므로 정답이다."},{"verdict":"오답","why":"지그비(Zigbee)는 저전력 근거리 무선 통신 기술로, 데이터 분석 기법이 아니다."},{"verdict":"오답","why":"디지털 트윈(Digital Twin)은 현실 사물을 가상 공간에 똑같이 구현한 모델이다."},{"verdict":"오답","why":"Wm-Bus(Wireless M-Bus)는 가스·수도·전기 계량기 원격 검침을 위한 무선 통신 규격이다."}],"keywords":[{"term":"데이터 마이닝(Data Mining)","desc":"대량 데이터에서 숨은 패턴과 관계를 찾는 기법"},{"term":"연관 규칙","desc":"함께 발생하는 항목의 관계를 찾는 데이터 마이닝 기법"},{"term":"Wm-Bus","desc":"계량기 원격 검침용 무선 통신 규격"}],"memo":"‘패턴을 찾는다’ = 마이닝(캐낸다)."}},{"id":"written-2025-3-95","no":95,"unit":"정보시스템 구축 관리","q":"시스템에 저장되는 패스워드는 Hash 또는 암호화 알고리즘의 결과 값으로 저장된다. 이때 암호 공격을 막기 위하여 동일한 패스워드라도 서로 다른 암호 값으로 저장되도록 추가하는 값을 의미하는 것은?","choices":["Bucket","Pass flag","Opcode","Salt"],"ans":4,"exp":{"concept":"솔트(Salt)는 패스워드를 해시하기 전에 덧붙이는 임의의 값이다. 같은 패스워드라도 솔트가 다르면 해시 결과가 달라지므로, 미리 계산해 둔 해시표(레인보우 테이블)로 패스워드를 알아내는 공격을 막을 수 있다. 음식에 소금을 뿌리면 맛이 달라지는 것처럼 결과값을 바꾼다.","choices":[{"verdict":"오답","why":"버킷(Bucket)은 해싱에서 같은 해시 주소를 갖는 레코드들을 저장하는 공간이다."},{"verdict":"오답","why":"Pass flag는 패스워드 저장과 관련된 표준 보안 용어가 아니다."},{"verdict":"오답","why":"Opcode(연산 코드)는 기계어 명령어에서 수행할 연산을 지정하는 부분이다."},{"verdict":"정답","why":"동일한 패스워드라도 서로 다른 해시값이 나오도록 추가하는 임의의 값은 솔트(Salt)이므로 정답이다."}],"keywords":[{"term":"솔트(Salt)","desc":"해시 전에 덧붙이는 임의 값, 같은 패스워드도 다른 해시값"},{"term":"레인보우 테이블","desc":"미리 계산한 해시값 표로 원래 패스워드를 찾는 공격 도구"},{"term":"해시(Hash)","desc":"임의 길이의 입력을 고정 길이 값으로 바꾸는 일방향 함수"}],"memo":"소금(Salt)을 치면 같은 재료도 다른 맛이 된다. 같은 패스워드도 다른 해시값."}},{"id":"written-2025-3-96","no":96,"unit":"정보시스템 구축 관리","q":"다음 중 CMMI의 단계에 해당하지 않는 것은?","choices":["정의","반복","관리","초기"],"ans":2,"exp":{"concept":"CMMI(Capability Maturity Model Integration)는 조직의 소프트웨어 개발 프로세스 성숙도를 평가하는 모델이다. 단계적 표현의 성숙도는 초기(Initial) → 관리(Managed) → 정의(Defined) → 정량적 관리(Quantitatively Managed) → 최적화(Optimizing)의 5단계다.","choices":[{"verdict":"오답","why":"정의(Defined)는 CMMI 3단계로, 조직 차원의 표준 프로세스를 정의해 활용하는 단계다."},{"verdict":"정답","why":"반복(Repeatable)은 CMMI의 단계가 아니다. 반복은 CMMI의 전신인 CMM에서 2단계를 부르던 이름이며, CMMI에서는 이 단계를 관리(Managed)라 한다."},{"verdict":"오답","why":"관리(Managed)는 CMMI 2단계로, 프로젝트별로 프로세스를 계획·관리하는 단계다."},{"verdict":"오답","why":"초기(Initial)는 CMMI 1단계로, 정해진 프로세스 없이 개인 역량에 의존하는 단계다."}],"keywords":[{"term":"CMMI 성숙도 5단계","desc":"초기 → 관리 → 정의 → 정량적 관리 → 최적화"},{"term":"정량적 관리","desc":"프로세스를 정량적으로 측정·통제하는 4단계"},{"term":"최적화","desc":"프로세스를 지속적으로 개선하는 5단계"}],"memo":"CMMI는 ‘초관정정최’(초기, 관리, 정의, 정량적 관리, 최적화). 반복은 옛 CMM의 이름이다."}},{"id":"written-2025-3-97","no":97,"unit":"정보시스템 구축 관리","q":"시스템 사용자가 로그인하여 명령을 내리는 과정에서 이루어지는 시스템의 동작 중 다음 설명에 해당하는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>자신의 신원(Identity)을 시스템에 증명하는 과정이다.</li><li>아이디와 패스워드를 입력하는 과정이 가장 일반적인 예시라고 할 수 있다.</li></ul></div>","choices":["Accounting","Authorization","Authentication","Aging"],"ans":3,"exp":{"concept":"시스템 접근 통제의 AAA는 인증(Authentication), 인가(Authorization), 계정 관리(Accounting)다. 인증은 ‘당신이 누구인지’ 증명하는 과정으로, 아이디와 패스워드 입력이 대표적이다. 인가는 인증된 사용자에게 무엇을 할 수 있는지 권한을 주는 과정이다.","choices":[{"verdict":"오답","why":"Accounting(계정 관리)은 사용자의 자원 사용 내역을 기록해 과금, 감사 등에 쓰는 과정이다."},{"verdict":"오답","why":"Authorization(인가)은 인증된 사용자에게 접근 권한을 부여하는 과정이다."},{"verdict":"정답","why":"자신의 신원을 시스템에 증명하는 과정은 Authentication(인증)이므로 정답이다."},{"verdict":"오답","why":"Aging(에이징)은 오래 기다린 프로세스의 우선순위를 점점 높여 무한 대기를 막는 스케줄링 기법으로, AAA 요소가 아니다."}],"keywords":[{"term":"Authentication(인증)","desc":"신원을 증명하는 과정, ID·패스워드 입력"},{"term":"Authorization(인가)","desc":"인증된 사용자에게 권한 부여"},{"term":"Accounting(계정 관리)","desc":"사용 내역 기록, 과금·감사"}],"memo":"AAA 순서는 ‘누구냐(인증) → 뭘 할 수 있냐(인가) → 뭘 했냐(계정 관리)’."}},{"id":"written-2025-3-98","no":98,"unit":"정보시스템 구축 관리","q":"하둡(Hadoop)과 관계형 데이터베이스 사이에서 데이터를 전송할 수 있게 설계된 도구는 무엇인가?","choices":["Sqoop","SDB","Apnic","Topology"],"ans":1,"exp":{"concept":"스쿱(Sqoop)은 하둡(Hadoop)과 관계형 데이터베이스(RDBMS) 사이에서 대량의 데이터를 주고받도록 만든 도구다. 이름도 SQL과 Hadoop을 합친 것이다.","choices":[{"verdict":"정답","why":"Sqoop은 하둡과 관계형 데이터베이스 사이에서 데이터를 전송하는 도구이므로 정답이다."},{"verdict":"오답","why":"SDB는 하둡과 관계형 데이터베이스 사이의 데이터 전송 도구를 가리키는 표준 용어가 아니다."},{"verdict":"오답","why":"APNIC(Asia Pacific Network Information Centre)은 아시아·태평양 지역의 IP 주소를 할당·관리하는 기관이다."},{"verdict":"오답","why":"토폴로지(Topology)는 네트워크를 구성하는 노드와 회선의 연결 형태(성형, 링형, 버스형 등)를 말한다."}],"keywords":[{"term":"Sqoop","desc":"하둡과 RDBMS 사이의 대량 데이터 전송 도구"},{"term":"하둡(Hadoop)","desc":"대용량 데이터를 분산 저장·처리하는 오픈 소스 프레임워크"},{"term":"척와(Chukwa)·플럼(Flume)","desc":"로그 등 비정형 데이터를 수집하는 도구"}],"memo":"Sqoop = SQL + Hadoop. 이름에 RDBMS(SQL)와 하둡이 다 들어 있다."}},{"id":"written-2025-3-99","no":99,"unit":"정보시스템 구축 관리","q":"코드 오류로 인해 발생할 수 있는 보안 약점 가운데 널 포인터(Null Pointer) 역참조가 일어나지 않도록 프로그래머가 해야 할 일로 가장 옳은 것은?","choices":["변수를 선언할 때 할당된 메모리를 초기화한다.","자원 반환 코드가 누락되지 않았는지 확인한다.","반환된 메모리에 접근하지 못하도록 주소를 저장하고 있는 포인터를 초기화한다.","포인터를 사용하기 전에 널 값을 갖고 있는지 검사한다."],"ans":4,"exp":{"concept":"널 포인터(Null Pointer) 역참조는 아무것도 가리키지 않는 포인터(NULL)를 통해 값을 읽거나 쓰려 할 때 생기는 오류다. 프로그램이 비정상 종료될 수 있으므로, 포인터를 사용하기 전에 NULL인지 먼저 검사해야 한다.","choices":[{"verdict":"오답","why":"변수를 선언할 때 메모리를 초기화하는 것은 초기화되지 않은 변수 사용을 막기 위한 조치다."},{"verdict":"오답","why":"자원 반환 코드 누락 여부를 확인하는 것은 부적절한 자원 해제(자원 누수)를 막기 위한 조치다."},{"verdict":"오답","why":"해제된 메모리를 가리키는 포인터를 초기화하는 것은 해제된 자원 사용(Use After Free)을 막기 위한 조치다."},{"verdict":"정답","why":"포인터를 사용하기 전에 널 값인지 검사하는 것이 널 포인터 역참조를 막는 직접적인 방법이므로 정답이다."}],"keywords":[{"term":"널 포인터 역참조","desc":"NULL 포인터로 메모리에 접근해 오류가 나는 보안 약점"},{"term":"해제된 자원 사용","desc":"이미 해제한 메모리를 다시 참조하는 보안 약점"},{"term":"부적절한 자원 해제","desc":"사용한 자원을 반환하지 않아 생기는 보안 약점"}],"memo":"널 포인터 문제의 해법은 하나, ‘쓰기 전에 NULL 검사’다."}},{"id":"written-2025-3-100","no":100,"unit":"정보시스템 구축 관리","q":"기존 무선 랜의 한계를 극복하기 위해 등장한 것으로, 대규모 디바이스의 네트워크 생성에 최적화되어 있어 차세대 이동통신, 홈네트워킹, 공공 안전 등 특수목적에 사용되는 새로운 방식의 네트워크 기술을 의미하는 것은?","choices":["Mesh Network","Local Area Network","Software Defined Perimeter","Virtual Private Network"],"ans":1,"exp":{"concept":"메시 네트워크(Mesh Network)는 여러 기기(노드)가 그물처럼 서로 직접 연결되어 데이터를 주고받는 네트워크다. 일부 노드에 문제가 생겨도 다른 경로로 전달할 수 있어, 대규모 디바이스 연결이나 재난·공공 안전 같은 특수 목적에 쓰인다.","choices":[{"verdict":"정답","why":"대규모 디바이스 네트워크 생성에 최적화되어 차세대 이동통신, 홈네트워킹, 공공 안전에 쓰이는 기술은 메시 네트워크이므로 정답이다."},{"verdict":"오답","why":"LAN(Local Area Network)은 건물이나 학교처럼 좁은 지역 안의 컴퓨터를 연결하는 근거리 통신망이다."},{"verdict":"오답","why":"SDP(Software Defined Perimeter)는 인증된 사용자와 기기에만 자원 접근을 허용하고 나머지에게는 자원을 숨기는 보안 프레임워크다."},{"verdict":"오답","why":"VPN(Virtual Private Network)은 공중망 위에 암호화된 터널을 만들어 사설망처럼 쓰는 가상 사설망이다."}],"keywords":[{"term":"메시 네트워크(Mesh Network)","desc":"노드들이 그물처럼 연결된 대규모 디바이스용 네트워크"},{"term":"VPN","desc":"공중망에서 암호화 터널로 사설망처럼 통신"},{"term":"SDP","desc":"인증된 사용자·기기에만 자원을 보이게 하는 보안 모델"}],"memo":"메시(Mesh)는 그물. 그물처럼 촘촘히 연결되어 대규모 기기를 수용한다."}}]};